1	import { Link, useNavigate } from "@tanstack/react-router";
2	import {
3		Background,
4		BackgroundVariant,
5		Controls,
6		type Edge,
7		Handle,
8		MarkerType,
9		type Node,
10		type NodeProps,
11		Position,
12		ReactFlow,
13		useNodesState,
14	} from "@xyflow/react";
15	import { Boxes, Pencil, Spline } from "lucide-react";
16	import {
17		type CSSProperties,
18		useCallback,
19		useEffect,
20		useMemo,
21		useState,
22	} from "react";
23	import { useMembers } from "@/hooks/use-members";
24	import { useOrgContext } from "@/hooks/use-org-context";
25	import {
26		TabEmptyState,
27		TabErrorState,
28	} from "@/components/entity-tabs/tab-states";
29	import { Button } from "@/components/ui/button";
30	import { EntityIcon } from "@/components/ui/entity-icon";
31	import { Skeleton } from "@/components/ui/skeleton";
32	import {
33		memoryBrowseTypeSearch,
34		memoryCreateEntityTypeSearch,
35	} from "@/lib/memory-browse";
36	import { cn } from "@/lib/utils";
37	import { labelledEdgeIds, type SchemaNodeData } from "./entity-schema-graph";
38	import { NewRelationshipDialog } from "./new-relationship-dialog";
39	import { useEntitySchemaGraph } from "./use-entity-schema-graph";
40	
41	import "@xyflow/react/dist/style.css";
42	
43	// React Flow v12 constrains node data to `Record<string, unknown>`. Widen only
44	// at this boundary — adding an index signature to `SchemaNodeData` itself would
45	// make every mistyped field access compile.
46	type SchemaFlowNode = Node<
47		SchemaNodeData & Record<string, unknown>,
48		"entityType"
49	>;
50	
51	function handleOffset(index: number, count: number): string {
52		return `${((index + 1) / (count + 1)) * 100}%`;
53	}
54	
55	/**
56	 * One entity type, drawn as a database-style table box: a header with the icon
57	 * and name, then its `metadata_schema` fields. Clicking opens that type's
58	 * records, the same destination the list view navigated to.
59	 */
60	function EntityTypeNode({ data, width, height }: NodeProps<SchemaFlowNode>) {
61		return (
62			<div className="group/node relative" style={{ width, height }}>
63				{data.targetHandleIds.map((handleId, index) => (
64					<Handle
65						key={handleId}
66						id={handleId}
67						type="target"
68						position={Position.Left}
69						style={{ top: handleOffset(index, data.targetHandleIds.length) }}
70						className="!border-0 !bg-muted-foreground/40"
71					/>
72				))}
73				{data.selfTargetHandleIds.map((handleId, index) => (
74					<Handle
75						key={handleId}
76						id={handleId}
77						type="target"
78						position={Position.Top}
79						style={{
80							left: handleOffset(index, data.selfTargetHandleIds.length),
81						}}
82						className="!border-0 !bg-muted-foreground/40"
83					/>
84				))}
85				{data.sourceHandleIds.map((handleId, index) => (
86					<Handle
87						key={handleId}
88						id={handleId}
89						type="source"
90						position={Position.Right}
91						style={{ top: handleOffset(index, data.sourceHandleIds.length) }}
92						className="!border-0 !bg-muted-foreground/40"
93					/>
94				))}
95	
96				<button
97					type="button"
98					aria-label={`Browse ${data.label} records`}
99					className={cn(
100						"h-full w-full cursor-pointer overflow-hidden rounded-lg border bg-card text-left shadow-sm transition-colors",
101						"hover:border-primary/60 hover:shadow-md",
102						"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
103						// Reserved `$…` types are shown but visually set apart so an
104						// intentionally empty schema does not look broken.
105						data.isSystem &&
106							"border-dashed border-muted-foreground/40 bg-muted/40",
107					)}
108				>
109					<span className="flex h-full items-center gap-2 px-3">
110						<EntityIcon icon={data.icon} className="h-4 w-4 shrink-0" />
111						<span className="min-w-0 flex-1 truncate text-sm font-semibold text-foreground">
112							{data.label}
113						</span>
114						{/* Boxes still say how much schema is behind them, so a header-only
115						    box never reads as a type with no fields. */}
116						{data.fields.length > 0 ? (
117							<span className="shrink-0 text-[11px] tabular-nums text-muted-foreground/60">
118								{data.fields.length}f
119							</span>
120						) : null}
121						{typeof data.entityCount === "number" ? (
122							<span className="shrink-0 pr-5 text-[11px] tabular-nums text-muted-foreground">
123								{data.entityCount}
124							</span>
125						) : null}
126					</span>
127				</button>
128	
129				{/* Sibling of the browse button, not a child — a button cannot nest a
130				    link. Schema editing (fields, relationships) lives in the existing
131				    entity-type form; this is the way in from the map. */}
132				<Link
133					to="/$owner/entity-types/$slug"
134					params={{ owner: data.ownerSlug, slug: data.slug }}
135					aria-label={`Edit ${data.label} schema`}
136					title="Edit schema"
137					onClick={(event) => event.stopPropagation()}
138					className={cn(
139						"absolute right-2 top-2.5 rounded p-1 text-muted-foreground/70 opacity-0 transition",
140						"hover:bg-accent hover:text-foreground focus-visible:opacity-100",
141						"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
142						"group-hover/node:opacity-100",
143					)}
144				>
145					<Pencil className="h-3 w-3" />
146				</Link>
147			</div>
148		);
149	}
150	
151	const NODE_TYPES = { entityType: EntityTypeNode };
152	
153	/**
154	 * Merge a freshly built graph into the nodes React Flow is currently showing,
155	 * keeping any position the user dragged a box to.
156	 *
157	 * Returns `current` unchanged when nothing rendered differs. That bail-out is
158	 * load bearing: the hook hands back a brand-new graph object every render (its
159	 * `rulesBySlug` comes from `useQueries`' combine), so a resync that always
160	 * produced a new array would be an infinite setState/render loop.
161	 *
162	 * Everything except position is compared, rather than a hand-listed subset —
163	 * a whitelist silently goes stale the moment a field is added to the node, and
164	 * has already caused renamed types and refreshed counts to keep displaying old
165	 * values.
166	 */
167	function mergeGraphIntoNodes(
168		current: SchemaFlowNode[],
169		next: SchemaFlowNode[],
170	): SchemaFlowNode[] {
171		const byId = new Map(current.map((node) => [node.id, node]));
172		let changed = current.length !== next.length;
173	
174		const merged = next.map((node, index) => {
175			const existing = byId.get(node.id);
176			if (!existing || current[index]?.id !== node.id) {
177				changed = true;
178				return node;
179			}
180			// Keep where the user put it; take everything else from the rebuild.
181			const candidate: SchemaFlowNode = { ...node, position: existing.position };
182			if (renderedStateOf(existing) === renderedStateOf(candidate)) return existing;
183			changed = true;
184			return candidate;
185		});
186	
187		return changed ? merged : current;
188	}
189	
190	/** Everything about a node that affects what is drawn or where it links. */
191	function renderedStateOf(node: SchemaFlowNode): string {
192		const { position: _position, ...rest } = node;
193		return JSON.stringify(rest);
194	}
195	
196	/**
197	 * Entities tab body when no type is scoped: an ERD of the workspace schema.
198	 *
199	 * Nodes are not directly editable. Clicking one opens its records, its pencil
200	 * opens the existing schema form, and the toolbar can add a declared
201	 * relationship. Boxes can be dragged to untangle a dense area, but positions
202	 * are not persisted — a reload returns to dagre's layout.
203	 */
204	export function EntityTypeGraphView({ ownerSlug }: { ownerSlug: string }) {
205		const navigate = useNavigate();
206		const { orgContext } = useOrgContext();
207		// Schema authoring (`create`, `add_rule`) is in OWNER_ADMIN_ACTIONS, while
208		// reading the map is public-read. Offering these to a member would only get
209		// them an authorization failure after they filled the dialog in.
210		const { isAdmin } = useMembers(orgContext.organizationId);
211		const [addingRelationship, setAddingRelationship] = useState(false);
212		// Boxes are headers only: the map is about how types relate, and full field
213		// lists on every box drown the edges out. Fields live in the type's editor.
214		const { graph, isLoading, isError, hasTypes } = useEntitySchemaGraph(ownerSlug);
215	
216		const laidOutNodes = useMemo<SchemaFlowNode[]>(
217			() =>
218				graph.nodes.map((node) => ({
219					id: node.id,
220					type: "entityType" as const,
221					position: node.position,
222					width: node.width,
223					height: node.height,
224					// Spread so the literal satisfies React Flow's `Record<string, unknown>`
225					// data constraint without loosening `SchemaNodeData`.
226					data: { ...node.data },
227				})),
228			[graph.nodes],
229		);
230	
231		// Dragging needs mutable node state, so React Flow owns positions once the
232		// canvas mounts. Nothing is persisted — a reload returns to dagre's layout.
233		const [nodes, setNodes, onNodesChange] = useNodesState(laidOutNodes);
234	
235		// `useNodesState` seeds from its argument once, so a rebuilt graph — a
236		// renamed type, a new relationship, a refreshed entity count — has to be
237		// pushed in. See `mergeGraphIntoNodes` for why it must bail out when nothing
238		// rendered actually changed.
239		useEffect(() => {
240			setNodes((current) => mergeGraphIntoNodes(current, laidOutNodes));
241		}, [laidOutNodes, setNodes]);
242	
243		const edges = useMemo<Edge[]>(() => {
244			const labelled = labelledEdgeIds(graph.edges);
245			return graph.edges.map((edge) => {
246				return {
247					id: edge.id,
248					source: edge.source,
249					target: edge.target,
250					sourceHandle: `${edge.id}-source`,
251					targetHandle: `${edge.id}-target`,
252					label: labelled.has(edge.id) ? edge.data.label : undefined,
253					className: "text-muted-foreground",
254					// A symmetric relation is an unordered pair, so an arrowhead would
255					// assert a direction the data does not have.
256					markerEnd: edge.data.isSymmetric
257						? undefined
258						: { type: MarkerType.ArrowClosed, width: 14, height: 14 },
259				};
260			});
261		}, [graph.edges]);
262	
263		const endpointOptions = useMemo(
264			() =>
265				graph.nodes
266					.map((node) => ({ slug: node.data.slug, label: node.data.label })),
267			[graph.nodes],
268		);
269	
270		// No drag/click disambiguation is needed: the browser does not emit a click
271		// after a press that moved the pointer (verified in-browser — a drag fires
272		// pointerdown/pointerup and no click), so React Flow never turns a drag into
273		// an `onNodeClick`.
274		const handleNodeClick = useCallback(
275			(_: unknown, node: SchemaFlowNode) => {
276				void navigate(
277					memoryBrowseTypeSearch(ownerSlug, node.data.slug, { view: "entities" }),
278				);
279			},
280			[navigate, ownerSlug],
281		);
282	
283		if (isLoading) {
284			return (
285				<div
286					role="status"
287					aria-label="Loading workspace schema"
288					className="flex min-h-0 w-full flex-1 flex-col"
289				>
290					<Skeleton className="min-h-[420px] w-full flex-1 rounded-lg" />
291				</div>
292			);
293		}
294	
295		if (isError) {
296			return <TabErrorState label="workspace schema" />;
297		}
298	
299		if (!hasTypes) {
300			return (
301				<TabEmptyState
302					icon={Boxes}
303					title="No entity types yet"
304					description={
305						isAdmin
306							? "Entity types define the records Memory can track — companies, people, tickets, and anything else you model. Create a type to get started."
307							: "Entity types define the records Memory can track. An admin can add the first one."
308					}
309					actionLabel={isAdmin ? "Create entity type" : undefined}
310					onAction={
311						isAdmin
312							? () => void navigate(memoryCreateEntityTypeSearch(ownerSlug))
313							: undefined
314					}
315				/>
316			);
317		}
318	
319		return (
320			// Full width, not a centered reading column: a schema map is only as useful
321			// as the space it gets, and the diagram grows with the workspace.
322			<div className="flex min-h-0 w-full flex-1 flex-col gap-3">
323				<div className="flex flex-wrap items-center justify-between gap-3">
324					<p className="text-sm text-muted-foreground">
325						{graph.edges.length > 0
326							? "Your workspace schema. Click a type to browse its records, or edit one to change its fields and relationships."
327							: "Your workspace schema. Click a type to browse its records — relationships appear here once you add one to a type."}
328					</p>
329					{isAdmin ? (
330						<div className="flex shrink-0 items-center gap-2">
331							<Button
332								type="button"
333								variant="outline"
334								size="sm"
335								className="h-8 text-xs"
336								onClick={() => setAddingRelationship(true)}
337							>
338								<Spline className="mr-1.5 h-3.5 w-3.5" />
339								New relationship
340							</Button>
341							<Button
342								type="button"
343								variant="outline"
344								size="sm"
345								className="h-8 text-xs"
346								onClick={() =>
347									void navigate(memoryCreateEntityTypeSearch(ownerSlug))
348								}
349							>
350								Create entity type
351							</Button>
352						</div>
353					) : null}
354				</div>
355	
356				<div className="min-h-[420px] w-full flex-1 overflow-hidden">
357					<ReactFlow
358						nodes={nodes}
359						edges={edges}
360						nodeTypes={NODE_TYPES}
361						onNodesChange={onNodesChange}
362						onNodeClick={handleNodeClick}
363						fitView
364						// Open at 1:1 so labels are readable on arrival rather than shrunk
365						// to fill the pane. `minZoom` floors the auto-fit well above the
366						// manual floor: a big schema still shrinks somewhat to show its
367						// shape, but never past readable, and pans for the rest.
368						fitViewOptions={{ minZoom: 0.7, maxZoom: 1, padding: 0.15 }}
369						// Boxes can be rearranged to untangle a dense area. Positions are
370						// not persisted — a reload returns to dagre's layout.
371						nodesDraggable
372						nodesConnectable={false}
373						nodesFocusable={false}
374						edgesFocusable={false}
375						proOptions={{ hideAttribution: true }}
376						minZoom={0.2}
377						maxZoom={1.5}
378						className="bg-background"
379						// xyflow defaults edge labels and the zoom controls to hardcoded
380						// white, which reads as a light patch on the canvas and is unusable
381						// in dark mode. These are its own theming variables, so drive them
382						// from the theme tokens rather than overriding the generated rules.
383						style={
384							{
385								"--xy-edge-label-background-color": "var(--background)",
386								"--xy-edge-label-color": "var(--muted-foreground)",
387								"--xy-controls-button-background-color": "var(--card)",
388								"--xy-controls-button-background-color-hover": "var(--accent)",
389								"--xy-controls-button-color": "var(--muted-foreground)",
390								"--xy-controls-button-color-hover": "var(--foreground)",
391								"--xy-controls-button-border-color": "var(--border)",
392								"--xy-controls-box-shadow": "0 1px 2px 0 rgb(0 0 0 / 0.05)",
393							} as CSSProperties
394						}
395					>
396						<Background variant={BackgroundVariant.Dots} gap={16} size={1} />
397						<Controls showInteractive={false} />
398					</ReactFlow>
399				</div>
400	
401				{/* Gated on its own, not just on the trigger being hidden — the dialog
402				    drives admin-only mutations regardless of how it was opened. */}
403				{isAdmin ? (
404					<NewRelationshipDialog
405						open={addingRelationship}
406						onOpenChange={setAddingRelationship}
407						entityTypes={endpointOptions}
408					/>
409				) : null}
410			</div>
411		);
412	}
