68		nodes: SchemaGraphNode[];
69		edges: SchemaGraphEdge[];
70	}
71	
72	/** Rules keyed by the relationship-type slug they belong to. */
73	export type RulesBySlug = Record<string, RelationshipTypeRule[]>;
