105	 * may also contain a public type with the same slug; `list_rules` resolves that
106	 * slug tenant-first, so keep the first type to label its rules consistently.
107	 */
108	export function selectRelationshipTypesForGraph(
109		relationshipTypes: RelationshipType[],
110	): RelationshipType[] {
111		const seen = new Set<string>();
112		return relationshipTypes.filter((relationshipType) => {
113			if (relationshipType.status !== "active") return false;
114			if (seen.has(relationshipType.slug)) return false;
115			seen.add(relationshipType.slug);
