121	 * Field rows for a type's box, read from its `metadata_schema` JSON-schema
122	 * `properties`. `$resource` is a deliberate graph anchor with an empty schema,
123	 * so an empty list is expected rather than a failure.
124	 */
125	export function schemaFields(entityType: EntityType): SchemaNodeField[] {
126		const schema = entityType.metadata_schema;
