135						? (spec as Record<string, unknown>).type
136						: undefined;
137				return { name, type: typeof type === "string" ? type : undefined };
138			},
139		);
140	}
141	
142	/**
143	 * Build the unpositioned graph. Only rules whose BOTH endpoints resolve to a
144	 * known type become edges — a rule naming a deleted type would otherwise
145	 * produce an edge to a node that does not exist.
146	 */
147	export function buildSchemaGraph(opts: {
148		entityTypes: EntityType[];
149		relationshipTypes: RelationshipType[];
150		rulesBySlug: RulesBySlug;
151		ownerSlug: string;
152	}): { nodes: Omit<SchemaGraphNode, "position">[]; edges: SchemaGraphEdge[] } {
153		const { entityTypes, relationshipTypes, rulesBySlug, ownerSlug } = opts;
154		const orderedEntityTypes = [...entityTypes].sort(compareSlugs);
155		const resolvedRelationshipTypes =
156			selectRelationshipTypesForGraph(relationshipTypes).sort(compareSlugs);
157	
158		const knownSlugs = new Set(orderedEntityTypes.map((et) => et.slug));
159		const edges: SchemaGraphEdge[] = [];
160		const sourceHandles = new Map<string, string[]>();
161		const targetHandles = new Map<string, string[]>();
162		const selfTargetHandles = new Map<string, string[]>();
163	
164		for (const rt of resolvedRelationshipTypes) {
165			const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);
