169				const target = rule.target_entity_type_slug;
170				if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;
171	
172				const edge = {
173					// Rule id keeps sibling rules of one relationship type distinct.
174					id: `rule-${rule.id}`,
175					source,
176					target,
177					data: {
178						slug: rt.slug,
179						label: rt.name || rt.slug,
180						isSymmetric: rt.is_symmetric,
181					},
182				};
183				edges.push(edge);
184				sourceHandles.set(source, [
185					...(sourceHandles.get(source) ?? []),
186					`${edge.id}-source`,
187				]);
188				const targetHandleMap =
189					source === target ? selfTargetHandles : targetHandles;
190				targetHandleMap.set(target, [
191					...(targetHandleMap.get(target) ?? []),
192					`${edge.id}-target`,
193				]);
194			}
195		}
196	
197		const nodes = orderedEntityTypes.map((et) => {
198			const fields = schemaFields(et);
199			return {
200				id: et.slug,
201				width: NODE_WIDTH,
202				// Header-only: the diagram is about relationships, and field lists
203				// compete with the edges for attention past a handful of types.
204				height: HEADER_HEIGHT,
205				data: {
206					slug: et.slug,
207					label: et.name || et.slug,
208					ownerSlug,
209					icon: et.icon,
210					fields,
211					isSystem: isSystemEntityType(et),
212					entityCount: et.entity_count,
213					sourceHandleIds: sourceHandles.get(et.slug) ?? [],
214					targetHandleIds: targetHandles.get(et.slug) ?? [],
215					selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
216				},
217			};
218		});
219	
220		return { nodes, edges };
221	}
222	
223	const MARGIN = 24;
224	/** Gap between the connected flow and the unconnected band beneath it. */
225	const BAND_GAP = 72;
226	
227	/**
228	 * Deterministic dagre layout — same input always yields the same arrangement,
229	 * so positions never need persisting and a reload does not reshuffle the map.
230	 *
231	 * Only types that a rule actually touches go through dagre. Unconnected types
232	 * have no edge to rank them, so dagre packs them into the first column, which
233	 * stretches the connected flow vertically and reads as if they belonged to it.
234	 * They get their own row beneath the diagram instead.
235	 */
236	function layoutSchemaGraph(graph: {
237		nodes: Omit<SchemaGraphNode, "position">[];
238		edges: SchemaGraphEdge[];
239	}): SchemaGraph {
240		const connected = new Set<string>();
241		for (const edge of graph.edges) {
242			connected.add(edge.source);
243			connected.add(edge.target);
244		}
245		const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
246		const bandNodes = graph.nodes.filter((node) => !connected.has(node.id));
247	
248		const g = new dagre.graphlib.Graph();
249		g.setGraph({
250			rankdir: "LR",
251			ranksep: 120,
252			nodesep: 32,
253			marginx: MARGIN,
254			marginy: MARGIN,
255		});
256		g.setDefaultEdgeLabel(() => ({}));
257	
258		for (const node of flowNodes) {
259			g.setNode(node.id, { width: node.width, height: node.height });
260		}
261		for (const edge of graph.edges) {
262			// Self-references do not separate ranks, so they do not participate in
263			// node layout. React Flow still receives and renders the edge.
264			if (edge.source === edge.target) continue;
265			g.setEdge(edge.source, edge.target);
266		}
267	
268		dagre.layout(g);
269	
270		const positioned = flowNodes.map((node) => {
271			const laidOut = g.node(node.id);
272			// dagre reports centers; React Flow positions from the top-left corner.
273			return {
274				...node,
275				position: {
276					x: (laidOut?.x ?? 0) - node.width / 2,
277					y: (laidOut?.y ?? 0) - node.height / 2,
278				},
279			};
280		});
281	
282		// Lay the unconnected band out left-to-right under the deepest flow node.
283		const flowBottom = positioned.reduce(
284			(max, node) => Math.max(max, node.position.y + node.height),
285			MARGIN,
286		);
287		const bandTop = positioned.length > 0 ? flowBottom + BAND_GAP : MARGIN;
288		let bandX = MARGIN;
289		const banded = bandNodes.map((node) => {
290			const position = { x: bandX, y: bandTop };
291			bandX += node.width + 32;
292			return { ...node, position };
293		});
294	
295		// Preserve the caller's node order so the output does not depend on which
296		// types happen to be connected.
297		const byId = new Map(
298			[...positioned, ...banded].map((node) => [node.id, node]),
299		);
300		const nodes = graph.nodes.map((node) => byId.get(node.id) ?? {
301			...node,
302			position: { x: MARGIN, y: MARGIN },
303		});
304	
305		return { nodes, edges: graph.edges };
306	}
307	
308	/** Build + lay out in one step. */
309	export function buildLaidOutSchemaGraph(opts: {
310		entityTypes: EntityType[];
311		relationshipTypes: RelationshipType[];
312		ownerSlug: string;
313		rulesBySlug: RulesBySlug;
314	}): SchemaGraph {
315		return layoutSchemaGraph(buildSchemaGraph(opts));
316	}
