347				);
348			}
349			// The band stacks down a single column, not across a row: a horizontal
350			// band grew the canvas sideways and pushed later types out of view.
351			expect(new Set(loose.map((n) => n.position.x)).size).toBe(1);
352			expect(new Set(loose.map((n) => n.position.y)).size).toBe(loose.length);
353		});
