356			const { nodes } = buildLaidOutSchemaGraph({
357				entityTypes: [entityType("goal"), entityType("note")],
358				relationshipTypes: [],
359				rulesBySlug: {},
360				ownerSlug: "acme",
361			});
362			// No flow to sit under, so the column starts at the top margin rather
363			// than being pushed down by an empty diagram.
364			expect(nodes.every((node) => node.position.x === nodes[0].position.x)).toBe(
365				true,
366			);
367			expect(nodes[0].position.y).toBe(24);
368			expect(new Set(nodes.map((node) => node.position.y)).size).toBe(2);
369		});
370	
371		it("assigns every node a finite position", () => {
372			const { nodes } = buildLaidOutSchemaGraph(input);
373			expect(nodes).toHaveLength(3);
374			for (const node of nodes) {
375				expect(Number.isFinite(node.position.x)).toBe(true);
376				expect(Number.isFinite(node.position.y)).toBe(true);
377			}
378		});
379	
380		it("separates connected types along the rank axis", () => {
381			const { nodes } = buildLaidOutSchemaGraph(input);
382			const person = nodes.find((n) => n.id === "person");
383			const company = nodes.find((n) => n.id === "company");
384			// rankdir LR ⇒ the edge target sits to the right of its source.
385			expect(company?.position.x).toBeGreaterThan(person?.position.x ?? 0);
386		});
387	
388		it("preserves a self-referencing rule without using it for node layout", () => {
389			const { nodes, edges } = buildLaidOutSchemaGraph({
390				entityTypes: [entityType("person")],
391				relationshipTypes: [relType("connected_with", { is_symmetric: true })],
392				rulesBySlug: { connected_with: [rule("person", "person")] },
393				ownerSlug: "acme",
394			});
395			// The self-loop is excluded from layout but must survive as an edge.
396			expect(edges).toHaveLength(1);
397			expect(nodes[0].data.targetHandleIds).toEqual([]);
398			expect(nodes[0].data.selfTargetHandleIds).toEqual([
399				`${edges[0].id}-target`,
400			]);
401			expect(Number.isFinite(nodes[0].position.x)).toBe(true);
402		});
403	
404		it("lays out an empty workspace without throwing", () => {
405			const { nodes, edges } = buildLaidOutSchemaGraph({
406				entityTypes: [],
407				relationshipTypes: [],
408				rulesBySlug: {},
409				ownerSlug: "acme",
410			});
411			expect(nodes).toEqual([]);
412			expect(edges).toEqual([]);
413		});
414	});
