import { describe, expect, it } from "vitest";
import type {
	EntityType,
	RelationshipType,
	RelationshipTypeRule,
} from "@/lib/api";
import {
	buildLaidOutSchemaGraph,
	buildSchemaGraph,
	labelledEdgeIds,
	schemaFields,
} from "./entity-schema-graph";

function entityType(
	slug: string,
	overrides: Partial<EntityType> = {},
): EntityType {
	return {
		id: Math.abs(hash(slug)),
		slug,
		name: slug,
		...overrides,
	} as EntityType;
}

function hash(s: string): number {
	let h = 0;
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
	return h;
}

function relType(
	slug: string,
	overrides: Partial<RelationshipType> = {},
): RelationshipType {
	return {
		id: Math.abs(hash(slug)),
		slug,
		name: slug,
		is_symmetric: false,
		status: "active",
		created_at: "",
		updated_at: "",
		...overrides,
	} as RelationshipType;
}

let ruleId = 0;
function rule(source: string, target: string): RelationshipTypeRule {
	ruleId += 1;
	return {
		id: ruleId,
		relationship_type_id: 0,
		source_entity_type_slug: source,
		target_entity_type_slug: target,
		created_at: "",
	};
}

describe("schemaFields", () => {
	it("reads JSON-schema properties into field rows", () => {
		const fields = schemaFields(
			entityType("company", {
				metadata_schema: {
					properties: { domain: { type: "string" }, mrr: { type: "number" } },
				},
			}),
		);
		expect(fields).toEqual([
			{ name: "domain", type: "string" },
			{ name: "mrr", type: "number" },
		]);
	});

	it("returns no fields for a graph-anchor type with an empty schema", () => {
		// `$resource` is deliberately schema-less — an empty list, not a crash.
		expect(schemaFields(entityType("$resource"))).toEqual([]);
		expect(
			schemaFields(entityType("$resource", { metadata_schema: {} })),
		).toEqual([]);
	});
});

describe("buildSchemaGraph", () => {
	it("turns each declared rule into its own edge", () => {
		// One relationship type with TWO rules must yield TWO edges — the reason
		// per-type counts cannot be used as per-edge labels.
		const { edges } = buildSchemaGraph({
			entityTypes: [
				entityType("person"),
				entityType("company"),
				entityType("org"),
			],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: {
				works_at: [rule("person", "company"), rule("person", "org")],
			},
			ownerSlug: "acme",
		});

		expect(edges).toHaveLength(2);
		expect(edges.map((e) => `${e.source}->${e.target}`)).toEqual([
			"person->company",
			"person->org",
		]);
		// Distinct ids, or React Flow silently drops the duplicate.
		expect(new Set(edges.map((e) => e.id)).size).toBe(2);
		expect(edges[0].data.label).toBe("works_at");
	});

	it("assigns distinct node handles to parallel rules", () => {
		const { nodes, edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("founded"), relType("works_at")],
			rulesBySlug: {
				founded: [rule("person", "company")],
				works_at: [rule("person", "company")],
			},
			ownerSlug: "acme",
		});
		const source = nodes.find((node) => node.id === "person");
		const target = nodes.find((node) => node.id === "company");

		expect(source?.data.sourceHandleIds).toEqual(
			edges.map((edge) => `${edge.id}-source`),
		);
		expect(target?.data.targetHandleIds).toEqual(
			edges.map((edge) => `${edge.id}-target`),
		);
	});

	it("flags system types instead of dropping them", () => {
		const { nodes } = buildSchemaGraph({
			entityTypes: [
				entityType("person"),
				entityType("$resource"),
				entityType("$member"),
			],
			relationshipTypes: [],
			rulesBySlug: {},
			ownerSlug: "acme",
		});

		const bySlug = Object.fromEntries(nodes.map((n) => [n.id, n.data]));
		expect(nodes).toHaveLength(3);
		expect(bySlug.person.isSystem).toBe(false);
		expect(bySlug.$resource.isSystem).toBe(true);
		expect(bySlug.$member.isSystem).toBe(true);
	});

	it("drops rules whose endpoints are not known types", () => {
		// A rule naming a deleted type would otherwise point at a missing node.
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person")],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: { works_at: [rule("person", "deleted_type")] },
			ownerSlug: "acme",
		});
		expect(edges).toEqual([]);
	});

	it("carries symmetry through to the edge", () => {
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person")],
			relationshipTypes: [relType("connected_with", { is_symmetric: true })],
			rulesBySlug: { connected_with: [rule("person", "person")] },
			ownerSlug: "acme",
		});
		expect(edges[0].data.isSymmetric).toBe(true);
	});

	it("handles a relationship type with no rules declared", () => {
		const { nodes, edges } = buildSchemaGraph({
			entityTypes: [entityType("person")],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: {},
			ownerSlug: "acme",
		});
		expect(edges).toEqual([]);
		expect(nodes[0].data.sourceHandleIds).toEqual([]);
		expect(nodes[0].data.targetHandleIds).toEqual([]);
	});

	it("uses the first accessible relationship type when a public slug is shadowed", () => {
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [
				relType("works_at", { id: 1, name: "Local works at" }),
				relType("works_at", { id: 2, name: "Public works at" }),
			],
			rulesBySlug: { works_at: [rule("person", "company")] },
			ownerSlug: "acme",
		});

		expect(edges).toHaveLength(1);
		expect(edges[0].data.label).toBe("Local works at");
	});

	it("does not render rules from archived relationship types", () => {
		const { edges } = buildSchemaGraph({
			entityTypes: [entityType("person"), entityType("company")],
			relationshipTypes: [relType("works_at", { status: "archived" })],
			rulesBySlug: { works_at: [rule("person", "company")] },
			ownerSlug: "acme",
		});

		expect(edges).toEqual([]);
	});

	it("gives every box a uniform header row regardless of field count", () => {
		// The map is about relationships; every box is the same small size so the
		// edges, not the field lists, carry the meaning. A 20-field type must not
		// grow taller than a bare one.
		const properties = Object.fromEntries(
			Array.from({ length: 20 }, (_, i) => [`f${i}`, { type: "string" }]),
		);
		const { nodes } = buildSchemaGraph({
			entityTypes: [
				entityType("bare"),
				entityType("wide", { metadata_schema: { properties } }),
			],
			relationshipTypes: [],
			rulesBySlug: {},
			ownerSlug: "acme",
		});
		const bare = nodes.find((n) => n.id === "bare");
		const wide = nodes.find((n) => n.id === "wide");

		expect(wide?.height).toBe(bare?.height);
		// The underlying fields are still carried, so the box can label its count.
		expect(wide?.data.fields).toHaveLength(20);
	});
});

describe("labelledEdgeIds", () => {
	function graphFor(pairs: [string, string, string][]) {
		const types = [...new Set(pairs.flatMap(([, s, t]) => [s, t]))];
		const slugs = [...new Set(pairs.map(([slug]) => slug))];
		const rulesBySlug: Record<string, ReturnType<typeof rule>[]> = {};
		for (const [slug, source, target] of pairs) {
			rulesBySlug[slug] ??= [];
			rulesBySlug[slug].push(rule(source, target));
		}
		return buildSchemaGraph({
			entityTypes: types.map((slug) => entityType(slug)),
			relationshipTypes: slugs.map((slug) => relType(slug)),
			rulesBySlug,
			ownerSlug: "acme",
		});
	}

	it("labels one edge per distinct pair, not per relationship type", () => {
		// `contains` joins two unrelated pairs. Labelling only its first edge
		// would leave invoice→payment captioned by order→product's rule.
		const { edges } = graphFor([
			["contains", "order", "product"],
			["contains", "invoice", "payment"],
		]);
		const labelled = labelledEdgeIds(edges);

		expect(edges).toHaveLength(2);
		expect(labelled.size).toBe(2);
	});

	it("labels only the first of several edges between the same pair", () => {
		// Two rules for one type on the SAME pair would stack identical text.
		const { edges } = graphFor([
			["works_at", "person", "company"],
			["works_at", "person", "company"],
		]);
		const labelled = labelledEdgeIds(edges);

		expect(edges).toHaveLength(2);
		expect(labelled.size).toBe(1);
		expect(labelled.has(edges[0].id)).toBe(true);
	});

	it("labels distinct relationship types sharing one pair", () => {
		// `works_at` and `founded` both join person→company; both need naming or
		// the diagram claims one relationship where there are two.
		const { edges } = graphFor([
			["works_at", "person", "company"],
			["founded", "person", "company"],
		]);

		expect(labelledEdgeIds(edges).size).toBe(2);
	});
});

describe("layoutSchemaGraph", () => {
	const input = {
		entityTypes: [
			entityType("person"),
			entityType("company"),
			entityType("goal"),
		],
		relationshipTypes: [relType("works_at")],
		rulesBySlug: { works_at: [rule("person", "company")] },
		ownerSlug: "acme",
	};

	it("is deterministic, so positions never need persisting", () => {
		const a = buildLaidOutSchemaGraph(input);
		const b = buildLaidOutSchemaGraph(input);
		expect(a.nodes.map((n) => n.position)).toEqual(
			b.nodes.map((n) => n.position),
		);
	});

	it("does not reshuffle when the API returns the same types in a new order", () => {
		const a = buildLaidOutSchemaGraph(input);
		const b = buildLaidOutSchemaGraph({
			...input,
			entityTypes: [...input.entityTypes].reverse(),
		});
		const positions = (graph: typeof a) =>
			Object.fromEntries(graph.nodes.map((node) => [node.id, node.position]));

		expect(positions(a)).toEqual(positions(b));
	});

	it("keeps unconnected types out of the connected flow's vertical span", () => {
		// Unconnected types have no edge to rank them, so dagre packs them into
		// the first column — several of them stretch the connected flow far down
		// the canvas and read as if they were part of it. They belong in their
		// own band underneath.
		const { nodes } = buildLaidOutSchemaGraph({
			entityTypes: [
				entityType("person"),
				entityType("company"),
				...Array.from({ length: 6 }, (_, i) => entityType(`loose${i}`)),
			],
			relationshipTypes: [relType("works_at")],
			rulesBySlug: { works_at: [rule("person", "company")] },
			ownerSlug: "acme",
		});
		const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
		const loose = nodes.filter((n) => n.id.startsWith("loose"));
		const flowTop = Math.min(byId.person.position.y, byId.company.position.y);

		// The connected pair starts at the top of the canvas. Left in dagre's
		// hands, six unranked boxes stack in the first column and push it down.
		expect(flowTop).toBeLessThan(loose[0].position.y);
		for (const node of loose) {
			expect(node.position.y).toBeGreaterThanOrEqual(
				byId.person.position.y + byId.person.height,
			);
		}
		// The band stacks down a single column, not across a row: a horizontal
		// band grew the canvas sideways and pushed later types out of view.
		expect(new Set(loose.map((n) => n.position.x)).size).toBe(1);
		expect(new Set(loose.map((n) => n.position.y)).size).toBe(loose.length);
	});

	it("keeps the band at the origin when nothing is connected", () => {
		const { nodes } = buildLaidOutSchemaGraph({
			entityTypes: [entityType("goal"), entityType("note")],
			relationshipTypes: [],
			rulesBySlug: {},
			ownerSlug: "acme",
		});
		// No flow to sit under, so the column starts at the top margin rather
		// than being pushed down by an empty diagram.
		expect(nodes.every((node) => node.position.x === nodes[0].position.x)).toBe(
			true,
		);
		expect(nodes[0].position.y).toBe(24);
		expect(new Set(nodes.map((node) => node.position.y)).size).toBe(2);
	});

	it("assigns every node a finite position", () => {
		const { nodes } = buildLaidOutSchemaGraph(input);
		expect(nodes).toHaveLength(3);
		for (const node of nodes) {
			expect(Number.isFinite(node.position.x)).toBe(true);
			expect(Number.isFinite(node.position.y)).toBe(true);
		}
	});

	it("separates connected types along the rank axis", () => {
		const { nodes } = buildLaidOutSchemaGraph(input);
		const person = nodes.find((n) => n.id === "person");
		const company = nodes.find((n) => n.id === "company");
		// rankdir LR ⇒ the edge target sits to the right of its source.
		expect(company?.position.x).toBeGreaterThan(person?.position.x ?? 0);
	});

	it("preserves a self-referencing rule without using it for node layout", () => {
		const { nodes, edges } = buildLaidOutSchemaGraph({
			entityTypes: [entityType("person")],
			relationshipTypes: [relType("connected_with", { is_symmetric: true })],
			rulesBySlug: { connected_with: [rule("person", "person")] },
			ownerSlug: "acme",
		});
		// The self-loop is excluded from layout but must survive as an edge.
		expect(edges).toHaveLength(1);
		expect(nodes[0].data.targetHandleIds).toEqual([]);
		expect(nodes[0].data.selfTargetHandleIds).toEqual([
			`${edges[0].id}-target`,
		]);
		expect(Number.isFinite(nodes[0].position.x)).toBe(true);
	});

	it("lays out an empty workspace without throwing", () => {
		const { nodes, edges } = buildLaidOutSchemaGraph({
			entityTypes: [],
			relationshipTypes: [],
			rulesBySlug: {},
			ownerSlug: "acme",
		});
		expect(nodes).toEqual([]);
		expect(edges).toEqual([]);
	});
});

