import { type UseQueryResult, useQueries } from "@tanstack/react-query";
import { useCallback, useMemo } from "react";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type RelationshipTypeRule,
	useEntityTypes,
	useRelationshipTypeRules,
	useRelationshipTypes,
} from "@/lib/api/entities";
import {
	buildLaidOutSchemaGraph,
	type RulesBySlug,
	selectRelationshipTypesForGraph,
} from "./entity-schema-graph";

/**
 * Data for the entity-type ERD.
 *
 * Unlike `useVisibleEntityTypes` (rail + scope bar) this KEEPS system types —
 * `$resource` is the ACL anchor for Slack channels and GitHub repos, so it is
 * one of the more informative nodes on the map. They are flagged, not dropped,
 * and the view colors them differently.
 *
 * Rules are fetched per relationship type (`list_rules` takes one slug), so this
 * is 1+N requests where N is the unique relationship-type count. A bulk rules
 * action can replace only this hook later;
 * `buildLaidOutSchemaGraph` is pure and does not care where rules came from.
 */
export function useEntitySchemaGraph(ownerSlug: string) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const {
		data: entityTypes = [],
		isLoading: isTypesLoading,
		isError: isTypesError,
	} = useEntityTypes(orgContext);
	const {
		data: relationshipTypes = [],
		isLoading: isRelTypesLoading,
		isError: isRelTypesError,
	} = useRelationshipTypes(orgContext);

	const scopedTypes = useMemo(
		() =>
			entityTypes.filter(
				(et) => !et.organization_slug || et.organization_slug === ownerSlug,
			),
		[entityTypes, ownerSlug],
	);

	const resolvedRelationshipTypes = useMemo(
		() => selectRelationshipTypesForGraph(relationshipTypes),
		[relationshipTypes],
	);

	const combineRuleQueries = useCallback(
		(results: UseQueryResult<RelationshipTypeRule[]>[]) => {
			const bySlug: RulesBySlug = {};
			resolvedRelationshipTypes.forEach((rt, idx) => {
				const rules = results[idx]?.data;
				if (rules?.length) bySlug[rt.slug] = rules;
			});
			return {
				rulesBySlug: bySlug,
				isRulesLoading: results.some((result) => result.isLoading),
				isRulesError: results.some((result) => result.isError),
			};
		},
		[resolvedRelationshipTypes],
	);

	// One `list_rules` per relationship type, run in parallel. `useQueries` takes
	// a dynamic-length list, so the query count can track the type count without
	// violating the rules of hooks.
	//
	// `.queryOptions()` does not carry the hook's `enabled` predicate, so gate
	// explicitly when there is no org context.
	const { rulesBySlug, isRulesLoading, isRulesError } = useQueries({
		queries: resolvedRelationshipTypes.map((rt) => ({
			...useRelationshipTypeRules.queryOptions(rt.slug, orgContext),
			enabled: hasOrgContext,
		})),
		// Fold the per-slug results in `combine` so the returned map is memoized on
		// the query results themselves. The callback must also be stable: TanStack
		// recomputes a combined result when the function identity changes.
		// Only derive rule-query state here. Entity types are not inputs to
		// `combine`, so graph construction belongs in the `useMemo` below.
		combine: combineRuleQueries,
	});

	const graph = useMemo(
		() =>
			buildLaidOutSchemaGraph({
				entityTypes: scopedTypes,
				relationshipTypes: resolvedRelationshipTypes,
				rulesBySlug,
				ownerSlug,
			}),
		[scopedTypes, resolvedRelationshipTypes, rulesBySlug, ownerSlug],
	);

	return {
		graph,
		// Edges arrive after nodes; treat the canvas as loading until rules settle
		// so the diagram never flashes a disconnected set of boxes.
		isLoading: isTypesLoading || isRelTypesLoading || isRulesLoading,
		isError: isTypesError || isRelTypesError || isRulesError,
		hasTypes: scopedTypes.length > 0,
	};
}

