// Keyed by relationship type AND ordered pair: `contains` joining
// order→product and invoice→payment is two distinct edges, while two
// `works_at` rules on person→company is one edge drawn with a count.
const byPair = new Map<string, SchemaGraphEdge>();

for (const rt of resolvedRelationshipTypes) {
	const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);

	for (const rule of rules) {
		const source = rule.source_entity_type_slug;
		const target = rule.target_entity_type_slug;
		if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;

		const pairKey = `${rt.slug}|${source}|${target}`;
		const collapsed = byPair.get(pairKey);
		if (collapsed) {
			collapsed.data.ruleCount += 1;
			collapsed.data.ruleIds.push(rule.id);
			continue;
		}

		const edge: SchemaGraphEdge = {
			// The first folded rule's id names the edge, so the id stays stable
			// as long as that rule exists.
			id: `rule-${rule.id}`,
			source,
			target,
			data: {
