const edges = useMemo<Edge[]>(() => {
	const labelled = labelledEdgeIds(graph.edges);
	// Only highlight when a cluster is actually picked — with nothing selected
	// every edge is equally relevant and dimming all of them helps no one.
	const focus = focusedCluster
		? new Set(focusedCluster.edgeIds)
		: undefined;

	return graph.edges.map((edge) => {
		const dimmed = focus ? !focus.has(edge.id) : false;
		// A collapsed edge says how many rules it stands for, so folding
		// siblings never hides that there is more than one.
		const label = labelled.has(edge.id)
			? edge.data.ruleCount > 1
				? `${edge.data.label} ×${edge.data.ruleCount}`
				: edge.data.label
			: undefined;

		return {
			id: edge.id,
			source: edge.source,
			target: edge.target,
			sourceHandle: `${edge.id}-source`,
			targetHandle: `${edge.id}-target`,
			label,
			// Orthogonal routing keeps parallel relationships in distinct lanes;
			// overlapping beziers between the same two boxes were unreadable.
			type: "smoothstep",
			pathOptions: { borderRadius: 12 },
			className: cn(
				"transition-opacity",
				dimmed ? "opacity-15" : "text-muted-foreground",
			),
			// A symmetric relation is an unordered pair, so an arrowhead would
			// assert a direction the data does not have.
			markerEnd: edge.data.isSymmetric
				? undefined
				: { type: MarkerType.ArrowClosed, width: 14, height: 14 },
		};
	});
}, [graph.edges, focusedCluster]);

