const NODE_TYPES = { entityType: EntityTypeNode };

/**
 * Right-hand index of the map: one row per cluster (a set of types joined by
 * relationships), then the types nothing links to.
 *
 * The canvas answers "how is this wired"; this answers "what groupings exist",
 * which a dense diagram hides. Selecting a cluster dims everything else rather
 * than hiding it, so the surrounding schema stays visible as context.
 */
function SchemaClusterPanel({
	clusters,
	islandSlugs,
	labelBySlug,
	focusedClusterId,
	onFocusCluster,
}: {
	clusters: SchemaCluster[];
	islandSlugs: string[];
	labelBySlug: Map<string, string>;
	focusedClusterId: string | null;
	onFocusCluster: (clusterId: string | null) => void;
}) {
	const labelOf = (slug: string) => labelBySlug.get(slug) ?? slug;

	return (
		<aside className="hidden w-60 shrink-0 flex-col gap-4 overflow-y-auto border-l pl-4 lg:flex">
			<div className="flex flex-col gap-2">
				<h3 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
					Clusters
				</h3>
				{clusters.length === 0 ? (
					<p className="text-xs text-muted-foreground">
						No relationships declared yet, so nothing is grouped.
					</p>
				) : (
					clusters.map((cluster) => {
						const isFocused = cluster.id === focusedClusterId;
						return (
							<button
								key={cluster.id}
								type="button"
								aria-pressed={isFocused}
								// Re-clicking the focused cluster clears the filter.
								onClick={() => onFocusCluster(isFocused ? null : cluster.id)}
								className={cn(
									"rounded-md border px-2.5 py-2 text-left transition-colors",
									"hover:border-primary/60 hover:bg-accent/50",
									"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
									isFocused ? "border-primary/70 bg-accent" : "border-border",
								)}
							>
								<span className="flex items-center justify-between gap-2">
									<span className="truncate text-xs font-medium text-foreground">
										{labelOf(cluster.slugs[0])}
									</span>
									<span className="shrink-0 text-[11px] tabular-nums text-muted-foreground">
										{cluster.slugs.length}
									</span>
								</span>
								<span className="mt-0.5 block truncate text-[11px] text-muted-foreground">
									{cluster.slugs.map(labelOf).join(", ")}
								</span>
							</button>
						);
					})
				)}
			</div>

			{islandSlugs.length > 0 ? (
				<div className="flex flex-col gap-1.5">
					<h3 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
						No relationships
					</h3>
					<p className="text-[11px] leading-relaxed text-muted-foreground">
						{islandSlugs.map(labelOf).join(", ")}
					</p>
				</div>
			) : null}
		</aside>
	);
}

