									"rounded-md border px-2.5 py-2 text-left transition-colors",
									"hover:border-primary/60 hover:bg-accent/50",
									"focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
									isFocused ? "border-primary/70 bg-accent" : "border-border",
								)}
							>
								<span className="flex items-center justify-between gap-2">
									<span className="truncate text-xs font-medium text-foreground">
										{labelOf(cluster.slugs[0])}
									</span>
									<span className="shrink-0 text-[11px] tabular-nums text-muted-foreground">
										{cluster.slugs.length}
									</span>
								</span>
								<span className="mt-0.5 block truncate text-[11px] text-muted-foreground">
									{cluster.slugs.map(labelOf).join(", ")}
								</span>
							</button>
						);
					})
				)}
			</div>

			{islandSlugs.length > 0 ? (
				<div className="flex flex-col gap-1.5">
					<h3 className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
						No relationships
					</h3>
					<p className="text-[11px] leading-relaxed text-muted-foreground">
						{islandSlugs.map(labelOf).join(", ")}
					</p>
				</div>
			) : null}
		</aside>
	);
}

