9	/**
10	 * Pure model + layout for the entity-type ERD.
11	 *
12	 * Boxes are entity TYPES (not rows); edges are the DECLARED
13	 * `entity_relationship_type_rules` (source→target slug pairs), so the diagram
14	 * renders correctly even for an org with zero entity rows. Kept free of React
15	 * and of the data-fetching layer so the shape logic is unit-testable and the
16	 * rules source can change (per-slug fan-out today, a bulk endpoint later)
17	 * without touching the view.
18	 */
19	
20	/** A field row rendered inside a type's box. */
21	export interface SchemaNodeField {
22		name: string;
23		/** JSON-schema type, when the property declares one. */
24		type?: string;
25	}
26	
27	export interface SchemaNodeData {
28		slug: string;
29		label: string;
30		/** Owner slug, so a node can link straight to its entity-type editor. */
31		ownerSlug: string;
32		icon?: string | null;
33		fields: SchemaNodeField[];
34		/** Reserved `$…` type, rendered in a distinct color rather than hidden. */
35		isSystem: boolean;
36		entityCount?: number;
37		/** Edge-specific handles keep parallel relationships from overlapping. */
38		sourceHandleIds: string[];
39		targetHandleIds: string[];
40		/** Self-loop targets attach above the node so their paths remain visible. */
41		selfTargetHandleIds: string[];
42		/**
43		 * Set by the view when a cluster is focused and this type is not in it.
44		 * Layout does not compute it — it is view state, carried on the node because
45		 * React Flow only hands the renderer `data`.
46		 */
47		isDimmed?: boolean;
48	}
49	
50	interface SchemaEdgeData {
51		/** Relationship type slug (`works_at`), not the rule id. */
52		slug: string;
53		label: string;
54		/** Symmetric relations render without an arrowhead — the pair is unordered. */
55		isSymmetric: boolean;
56		/**
57		 * How many declared rules this one drawn edge stands for.
58		 *
59		 * Sibling rules of one relationship type on the same ordered pair are drawn
60		 * once with a count rather than as parallel paths: they carry identical text
61		 * and identical endpoints, so N paths added N crossings and zero information.
62		 */
63		ruleCount: number;
64		/** Every rule id folded into this edge, so the view can expand it on demand. */
65		ruleIds: number[];
66	}
67	
68	interface SchemaGraphNode {
69		id: string;
70		data: SchemaNodeData;
71		position: { x: number; y: number };
72		width: number;
73		height: number;
74	}
75	
76	export interface SchemaGraphEdge {
77		id: string;
78		source: string;
79		target: string;
80		data: SchemaEdgeData;
81	}
82	
83	interface SchemaGraph {
84		nodes: SchemaGraphNode[];
85		edges: SchemaGraphEdge[];
86		/** Connected components, biggest first. Islands are excluded — see `schemaClusters`. */
87		clusters: SchemaCluster[];
88		/** Slugs of types no declared rule touches, in the order they are laid out. */
89		islandSlugs: string[];
90	}
91	
92	/** Rules keyed by the relationship-type slug they belong to. */
93	export type RulesBySlug = Record<string, RelationshipTypeRule[]>;
94	
95	/**
96	 * Which edges should carry a visible label.
97	 *
98	 * Parallel edges between the same pair stack identical text in the same spot,
99	 * so only the first of a pair is labelled. Keyed by the PAIR rather than by
100	 * relationship type: one type can join several different pairs (`contains`
101	 * covers order→product and invoice→payment), and keying by type alone would
102	 * caption an unrelated pair with the first pair's name.
103	 */
104	export function labelledEdgeIds(edges: SchemaGraphEdge[]): Set<string> {
105		const seenPairs = new Set<string>();
106		const labelled = new Set<string>();
107		for (const edge of edges) {
108			const pairKey = `${edge.data.slug}|${edge.source}|${edge.target}`;
109			if (seenPairs.has(pairKey)) continue;
110			seenPairs.add(pairKey);
111			labelled.add(edge.id);
112		}
113		return labelled;
114	}
115	
116	const NODE_WIDTH = 220;
117	const HEADER_HEIGHT = 44;
118	
119	function compareSlugs(a: { slug: string }, b: { slug: string }): number {
120		return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
121	}
122	
123	/**
124	 * Keep active relationship types only. The accessible list is tenant-first and
125	 * may also contain a public type with the same slug; `list_rules` resolves that
126	 * slug tenant-first, so keep the first type to label its rules consistently.
127	 */
128	export function selectRelationshipTypesForGraph(
129		relationshipTypes: RelationshipType[],
130	): RelationshipType[] {
131		const seen = new Set<string>();
132		return relationshipTypes.filter((relationshipType) => {
133			if (relationshipType.status !== "active") return false;
134			if (seen.has(relationshipType.slug)) return false;
135			seen.add(relationshipType.slug);
136			return true;
137		});
138	}
139	
140	/**
141	 * Field rows for a type's box, read from its `metadata_schema` JSON-schema
142	 * `properties`. `$resource` is a deliberate graph anchor with an empty schema,
143	 * so an empty list is expected rather than a failure.
144	 */
145	export function schemaFields(entityType: EntityType): SchemaNodeField[] {
146		const schema = entityType.metadata_schema;
147		if (!schema || typeof schema !== "object") return [];
148		const properties = (schema as Record<string, unknown>).properties;
149		if (!properties || typeof properties !== "object") return [];
150	
151		return Object.entries(properties as Record<string, unknown>).map(
152			([name, spec]) => {
153				const type =
