// @vitest-environment jsdom
import { render, screen } from "@testing-library/react";
import { useState } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = {
	isAdmin: true,
	hasTypes: true,
	// Handle ids change when a relationship is added without changing the node
	// set or its heights.
	sourceHandleIds: [] as string[],
	label: "Person",
	entityCount: 0,
};

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({
		orgContext: { organizationId: "org-1", slug: "acme" },
		hasOrgContext: true,
	}),
}));

vi.mock("@/hooks/use-members", () => ({
	useMembers: () => ({
		members: [],
		isLoading: false,
		currentUserRole: mocks.isAdmin ? "admin" : "member",
		isAdmin: mocks.isAdmin,
	}),
}));

// NOTE: these tests cannot catch render loops caused by the real hook's
// identity churn — jsdom does not re-render on the post-mount setState that
// drives them (measured: 1 render). The node-state resync in the view is
// guarded by browser checking, not by this file.
vi.mock("./use-entity-schema-graph", () => ({
	useEntitySchemaGraph: () => ({
		graph: {
			nodes: mocks.hasTypes
				? [
						{
							id: "person",
							position: { x: 0, y: 0 },
							width: 220,
							height: 44,
							data: {
								slug: "person",
								label: mocks.label,
								ownerSlug: "acme",
								fields: [],
								isSystem: false,
								entityCount: mocks.entityCount,
								sourceHandleIds: mocks.sourceHandleIds,
								targetHandleIds: [],
								selfTargetHandleIds: [],
							},
						},
					]
				: [],
			edges: [],
		},
		isLoading: false,
		isError: false,
		hasTypes: mocks.hasTypes,
	}),
}));

// React Flow needs layout APIs jsdom does not implement. Capture the props it
// is handed so the drag/click callbacks can be driven directly — that logic is
// ours, even though the gesture that triggers it is the library's.
const flowProps: { current: Record<string, unknown> } = { current: {} };

vi.mock("@xyflow/react", () => ({
	ReactFlow: ({
		children,
		...props
	}: {
		children?: React.ReactNode;
		[key: string]: unknown;
	}) => {
		flowProps.current = props;
		return <div data-testid="react-flow">{children}</div>;
	},
	Background: () => null,
	Controls: () => null,
	Handle: () => null,
	BackgroundVariant: { Dots: "dots" },
	MarkerType: { ArrowClosed: "arrowclosed" },
	Position: { Left: "left", Right: "right", Top: "top", Bottom: "bottom" },
	useNodesState: (initial: unknown[]) => {
		const [value, setValue] = useState(initial);
		return [value, setValue, vi.fn()];
	},
}));

const navigateSpy = vi.fn();

vi.mock("@tanstack/react-router", () => ({
	useNavigate: () => navigateSpy,
	Link: ({ children }: { children?: React.ReactNode }) => <a href="/">{children}</a>,
}));

// `memory-browse` reaches into real router search serialization, which needs a
// router instance this component test does not build.
vi.mock("@/lib/memory-browse", () => ({
	memoryBrowseTypeSearch: () => ({ to: "/$owner/memory" }),
	memoryCreateEntityTypeSearch: () => ({ to: "/$owner/memory" }),
}));

vi.mock("./new-relationship-dialog", () => ({
	NewRelationshipDialog: () => <div data-testid="new-relationship-dialog" />,
}));

import { EntityTypeGraphView } from "./entity-type-graph-view";

beforeEach(() => {
	mocks.isAdmin = true;
	mocks.hasTypes = true;
	mocks.sourceHandleIds = [];
	mocks.label = "Person";
	mocks.entityCount = 0;
	navigateSpy.mockReset();
	flowProps.current = {};
});

type DragHandler = (event: unknown, node: unknown) => void;

function node(x: number, y: number) {
	return { id: "person", position: { x, y }, data: { slug: "person" } };
}

describe("EntityTypeGraphView canvas", () => {
	it("browses the type when a box is clicked", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const onClick = flowProps.current.onNodeClick as DragHandler;

		onClick({}, node(0, 0));

		expect(navigateSpy).toHaveBeenCalledTimes(1);
	});

	it("lets boxes be dragged", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		expect(flowProps.current.nodesDraggable).toBe(true);
	});

	it("pushes a renamed type through even though handles are unchanged", () => {
		// A whitelist signature that only covered ids/sizes/handles left renames
		// and refreshed counts displaying stale values until remount.
		const { rerender } = render(<EntityTypeGraphView ownerSlug="acme" />);
		const read = () =>
			(flowProps.current.nodes as { data: { label: string; entityCount?: number } }[])[0].data;
		expect(read().label).toBe("Person");

		mocks.label = "Human";
		mocks.entityCount = 12;
		rerender(<EntityTypeGraphView ownerSlug="acme" />);

		expect(read().label).toBe("Human");
		expect(read().entityCount).toBe(12);
	});

	it("pushes new handles through when a relationship is added", () => {
		// Adding a relationship leaves the node set and heights identical but
		// gives the endpoints new handles. If the resync bails out on those, the
		// edge references handles its nodes do not have and React Flow drops it —
		// the relationship stays invisible until a reload.
		const { rerender } = render(<EntityTypeGraphView ownerSlug="acme" />);
		expect(
			(flowProps.current.nodes as { data: { sourceHandleIds: string[] } }[])[0]
				.data.sourceHandleIds,
		).toEqual([]);

		mocks.sourceHandleIds = ["works_at-0-source"];
		rerender(<EntityTypeGraphView ownerSlug="acme" />);

		expect(
			(flowProps.current.nodes as { data: { sourceHandleIds: string[] } }[])[0]
				.data.sourceHandleIds,
		).toEqual(["works_at-0-source"]);
	});
});

describe("EntityTypeGraphView authoring affordances", () => {
	it("offers schema authoring to admins", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(
			screen.getByRole("button", { name: "New relationship" }),
		).toBeTruthy();
		expect(
			screen.getByRole("button", { name: "Create entity type" }),
		).toBeTruthy();
	});

	it("hides schema authoring from non-admin members", () => {
		// `create` and `add_rule` are OWNER_ADMIN_ACTIONS server-side, so showing
		// these to a member only buys them an authorization failure after they
		// have filled the dialog in.
		mocks.isAdmin = false;
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(screen.queryByRole("button", { name: "New relationship" })).toBeNull();
		expect(
			screen.queryByRole("button", { name: "Create entity type" }),
		).toBeNull();
		// The dialog is gated on its own, not merely on its trigger being hidden.
		expect(screen.queryByTestId("new-relationship-dialog")).toBeNull();
		// Reading the map stays public — the member still sees the schema.
		expect(screen.getByTestId("react-flow")).toBeTruthy();
	});

	it("does not push a non-admin toward a create they cannot perform", () => {
		mocks.isAdmin = false;
		mocks.hasTypes = false;
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(screen.getByText("No entity types yet")).toBeTruthy();
		expect(
			screen.queryByRole("button", { name: "Create entity type" }),
		).toBeNull();
	});
});

