clusters = '''
/**
 * A set of entity types reachable from one another through declared
 * relationships — one connected component of the schema graph.
 *
 * Clusters are what the map is actually showing: "these six types form your CRM,
 * these three are the ops side, and these nine are islands". Surfaced so the
 * view can list them and zoom to one.
 */
export interface SchemaCluster {
	/** Stable id: the alphabetically first member slug. */
	id: string;
	/** Member type slugs, sorted. */
	slugs: string[];
	/** Ids of edges whose endpoints are both in this cluster. */
	edgeIds: string[];
}

/**
 * Group connected types into clusters via union-find over the declared edges.
 *
 * Unconnected types are deliberately EXCLUDED — a component of one node is not
 * a cluster, it is an island, and listing nine single-node "clusters" buries the
 * one grouping that carries meaning. The view lists islands separately.
 */
export function schemaClusters(graph: {
	nodes: { id: string }[];
	edges: SchemaGraphEdge[];
}): SchemaCluster[] {
	const parent = new Map<string, string>();
	const find = (slug: string): string => {
		const seen = parent.get(slug);
		if (seen === undefined || seen === slug) return slug;
		const root = find(seen);
		parent.set(slug, root);
		return root;
	};
	const union = (a: string, b: string) => {
		const rootA = find(a);
		const rootB = find(b);
		if (rootA !== rootB) parent.set(rootA, rootB);
	};

	for (const node of graph.nodes) parent.set(node.id, node.id);
	// A self-loop connects a type to itself, which makes it a real (one-node)
	// cluster rather than an island — it has a relationship to show.
	for (const edge of graph.edges) union(edge.source, edge.target);

	const connected = new Set<string>();
	for (const edge of graph.edges) {
		connected.add(edge.source);
		connected.add(edge.target);
	}

	const byRoot = new Map<string, string[]>();
	for (const node of graph.nodes) {
		if (!connected.has(node.id)) continue;
		const root = find(node.id);
		byRoot.set(root, [...(byRoot.get(root) ?? []), node.id]);
	}

	const clusters = [...byRoot.values()].map((slugs) => {
		const members = [...slugs].sort();
		const memberSet = new Set(members);
		return {
			id: members[0],
			slugs: members,
			edgeIds: graph.edges
				.filter(
					(edge) => memberSet.has(edge.source) && memberSet.has(edge.target),
				)
				.map((edge) => edge.id),
		};
	});

	// Biggest first — the largest component is the one worth reading first — then
	// by id so the order never depends on map-iteration order.
	return clusters.sort(
		(a, b) =>
			b.slugs.length - a.slugs.length ||
			(a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
	);
}

const MARGIN = 24;'''

