// @vitest-environment jsdom
import { render, screen } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';

const mocks = {
  data: undefined as { workspace?: unknown } | undefined,
  isLoading: false,
  isError: false,
  error: null as Error | null,
  session: { user: { id: 'u1' } } as unknown,
};

vi.mock('@/lib/api', () => ({
  useWorkspaceRoot: () => ({
    data: mocks.data,
    isLoading: mocks.isLoading,
    isError: mocks.isError,
    error: mocks.error,
  }),
}));

vi.mock('@/lib/auth-state', () => ({
  useAuthState: () => ({ session: mocks.session, isReady: true }),
}));

const navigateSpy = vi.fn();
vi.mock('@tanstack/react-router', () => ({
  useNavigate: () => navigateSpy,
}));

import { OwnerWorkspaceGate } from './owner-workspace-gate';

beforeEach(() => {
  mocks.data = undefined;
  mocks.isLoading = false;
  mocks.isError = false;
  mocks.error = null;
  mocks.session = { user: { id: 'u1' } };
  navigateSpy.mockReset();
});

function renderGate() {
  return render(
    <OwnerWorkspaceGate owner="acme">
      {({ organizationId }) => <div data-testid="body">{organizationId}</div>}
    </OwnerWorkspaceGate>,
  );
}

describe('OwnerWorkspaceGate', () => {
  it('reports a server failure as an error, not as a missing organization', () => {
    // A 500 leaves `data` undefined exactly like a real 404 does. Keying the
    // empty state on `!workspace` alone told the user their org did not exist
    // when the server had actually failed — sending them to re-check a slug
    // that was correct all along.
    mocks.isError = true;
    mocks.error = new Error('Request failed with status 500');

    renderGate();

    expect(screen.queryByText('Organization not found')).toBeNull();
    expect(screen.getByRole('alert')).toBeTruthy();
    expect(screen.getByText(/could not be loaded/i)).toBeTruthy();
  });

  it('still reports a genuinely missing organization as not found', () => {
    // The 404 path must keep its own wording — the fix must not turn every
    // missing org into a scary server error.
    mocks.data = {};

    renderGate();

    expect(screen.getByText('Organization not found')).toBeTruthy();
    expect(screen.queryByRole('alert')).toBeNull();
  });

  it('renders the workspace body once it resolves', () => {
    mocks.data = { workspace: { type: 'organization', id: 'org_1', slug: 'acme' } };

    renderGate();

    expect(screen.getByTestId('body').textContent).toBe('org_1');
  });

  it('does not show either empty state while the request is in flight', () => {
    mocks.isLoading = true;

    renderGate();

    expect(screen.queryByText('Organization not found')).toBeNull();
    expect(screen.queryByRole('alert')).toBeNull();
    expect(screen.getByTestId('body')).toBeTruthy();
  });

  it('does not bounce an errored request to the login page', () => {
    // The redirect fires on "no session and no workspace". A failed request
    // also has no workspace, so an unauthenticated 500 logged the user out of
    // the page they were on instead of surfacing the outage.
    mocks.session = null;
    mocks.isError = true;
    mocks.error = new Error('boom');

    renderGate();

    expect(navigateSpy).not.toHaveBeenCalled();
  });
});

