new_layout = '''/**
 * ELK's layered layout with ORTHOGONAL edge routing.
 *
 * dagre (layered/Sugiyama too) minimizes crossings between adjacent ranks but
 * gives edges no separation of their own, so several relationships between the
 * same two boxes drew as overlapping curves — the hairball this replaced. ELK
 * routes edges as right-angled lanes and honours `spacing.edgeEdge*`, so
 * parallel relationships stay visually distinct.
 *
 * Deterministic: ELK is seeded by input order and `layoutSchemaGraph` always
 * feeds it slug-sorted nodes, so the same schema always lays out the same way
 * and positions never need persisting.
 *
 * Async because ELK's API is promise-based. Only types a rule actually touches
 * are laid out; unconnected types have no edge to rank them and get their own
 * column at the top left.
 */
const elk = new ELK();

/** Tuned for a schema map: wide lanes between ranks, real gaps between edges. */
const ELK_OPTIONS: Record<string, string> = {
	"elk.algorithm": "layered",
	"elk.direction": "RIGHT",
	"elk.edgeRouting": "ORTHOGONAL",
	// The lane spacings. Without these ELK packs parallel edges flush against
	// each other and the orthogonal routing buys nothing.
	"elk.layered.spacing.edgeEdgeBetweenLayers": "12",
	"elk.layered.spacing.edgeNodeBetweenLayers": "24",
	"elk.layered.spacing.nodeNodeBetweenLayers": "120",
	"elk.spacing.nodeNode": "32",
	"elk.spacing.edgeEdge": "12",
	"elk.spacing.edgeNode": "20",
	// Keep a node's own edges in the order its handles are rendered, so an
	// edge's line meets the handle it is anchored to instead of crossing to it.
	"elk.layered.considerModelOrder.strategy": "NODES_AND_EDGES",
	"elk.layered.crossingMinimization.semiInteractive": "true",
};

async function layoutSchemaGraph(graph: {
	nodes: Omit<SchemaGraphNode, "position">[];
	edges: SchemaGraphEdge[];
}): Promise<SchemaGraph> {
	const connected = new Set<string>();
	for (const edge of graph.edges) {
		connected.add(edge.source);
		connected.add(edge.target);
	}
	const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
	const bandNodes = graph.nodes.filter((node) => !connected.has(node.id));

	// Islands take a column at the top LEFT, so the connected flow starts to the
	// right of them instead of below them. Under the flow they sat off the bottom
	// of the viewport on arrival; beside it they read as a legend of the types
	// that simply have no relationships yet, visible without scrolling.
	const bandWidth = bandNodes.reduce(
		(max, node) => Math.max(max, node.width),
		0,
	);
	const flowOffsetX = bandNodes.length > 0 ? MARGIN + bandWidth + BAND_GAP : 0;

	let positioned: SchemaGraphNode[] = [];
	if (flowNodes.length > 0) {
		const laidOut = await elk.layout({
			id: "root",
			layoutOptions: ELK_OPTIONS,
			children: flowNodes.map((node) => ({
				id: node.id,
				width: node.width,
				height: node.height,
			})),
			// Self-references do not separate ranks and ELK rejects some of them
			// outright, so they are excluded from layout. React Flow still receives
			// and renders the edge.
			edges: graph.edges
				.filter((edge) => edge.source !== edge.target)
				.map((edge) => ({
					id: edge.id,
					sources: [edge.source],
					targets: [edge.target],
				})),
		});

		const byLaidOutId = new Map(
			(laidOut.children ?? []).map((child) => [child.id, child]),
		);
		positioned = flowNodes.map((node) => {
			const child = byLaidOutId.get(node.id);
			// ELK reports top-left corners already, unlike dagre's centers.
			return {
				...node,
				position: {
					x: (child?.x ?? 0) + MARGIN + flowOffsetX,
					y: (child?.y ?? 0) + MARGIN,
				},
			};
		});
	}

	// The column starts at the top margin rather than below the diagram — under
	// the flow the islands landed off the bottom of the viewport on arrival.
	let bandY = MARGIN;
	const banded = bandNodes.map((node) => {
		const position = { x: MARGIN, y: bandY };
		bandY += node.height + BAND_ROW_GAP;
		return { ...node, position };
	});

	// Preserve the caller's node order so the output does not depend on which
	// types happen to be connected.
	const byId = new Map(
		[...positioned, ...banded].map((node) => [node.id, node]),
	);
	const nodes = graph.nodes.map(
		(node) =>
			byId.get(node.id) ?? {
				...node,
				position: { x: MARGIN, y: MARGIN },
			},
	);

	return {
		nodes,
		edges: graph.edges,
		clusters: schemaClusters(graph),
		islandSlugs: bandNodes.map((node) => node.id),
	};
}

