	// ELK's API is promise-based, so the laid-out graph arrives after the render
	// that requested it and has to live in state rather than a `useMemo`.
	const [graph, setGraph] = useState<SchemaGraph>(EMPTY_GRAPH);
	const [isLayingOut, setIsLayingOut] = useState(false);

	useEffect(() => {
		// Two layout runs can be in flight when the inputs change mid-run, and
		// they are not guaranteed to settle in order. Ignore all but the newest,
		// or a slow earlier run can overwrite the current graph.
		let cancelled = false;
		setIsLayingOut(true);

		buildLaidOutSchemaGraph({
			entityTypes: scopedTypes,
			relationshipTypes: resolvedRelationshipTypes,
			rulesBySlug,
			ownerSlug,
		})
			.then((next) => {
				if (cancelled) return;
				setGraph(next);
				setIsLayingOut(false);
			})
			.catch(() => {
				// A layout failure must not strand the canvas in a permanent
				// skeleton; surface it as an error the view already knows how to
				// render.
				if (cancelled) return;
				setGraph(EMPTY_GRAPH);
				setIsLayingOut(false);
				setDidLayoutFail(true);
			});

		return () => {
			cancelled = true;
		};
	}, [scopedTypes, resolvedRelationshipTypes, rulesBySlug, ownerSlug]);

	const [didLayoutFail, setDidLayoutFail] = useState(false);

	return {
		graph,
		// Edges arrive after nodes; treat the canvas as loading until rules settle
		// so the diagram never flashes a disconnected set of boxes. Layout itself
		// is part of that wait now that it is async.
		isLoading:
			isTypesLoading || isRelTypesLoading || isRulesLoading || isLayingOut,
		isError:
			isTypesError || isRelTypesError || isRulesError || didLayoutFail,
		hasTypes: scopedTypes.length > 0,
	};
}

