function mergeGraphIntoNodes(
	current: SchemaFlowNode[],
	next: SchemaFlowNode[],
): SchemaFlowNode[] {
	const byId = new Map(current.map((node) => [node.id, node]));
	let changed = current.length !== next.length;

	const merged = next.map((node, index) => {
		const existing = byId.get(node.id);
		if (!existing || current[index]?.id !== node.id) {
			changed = true;
			return node;
		}
		// Keep where the user put it; take everything else from the rebuild.
		const candidate: SchemaFlowNode = { ...node, position: existing.position };
		if (renderedStateOf(existing) === renderedStateOf(candidate))
			return existing;
		changed = true;
		return candidate;
	});

	return changed ? merged : current;
}

