const laidOutNodes = useMemo<SchemaFlowNode[]>(() => {
	const focusedSlugs = focusedCluster ? new Set(focusedCluster.slugs) : null;
	return graph.nodes.map((node) => ({
		id: node.id,
		type: "entityType" as const,
		position: node.position,
		width: node.width,
		height: node.height,
		// Spread so the literal satisfies React Flow's `Record<string, unknown>`
		// data constraint without loosening `SchemaNodeData`.
		data: {
			...node.data,
			isDimmed: focusedSlugs ? !focusedSlugs.has(node.id) : false,
			// Where layout put this box, kept so a later rebuild can tell a
			// re-layout apart from a box the user dragged.
			laidOutPosition: node.position,
		},
	}));
}, [graph.nodes, focusedCluster]);

// Dragging needs mutable node state, so React Flow owns positions once the
// canvas mounts. Nothing is persisted — a reload returns to the computed layout.
const [nodes, setNodes, onNodesChange] = useNodesState(laidOutNodes);

