while (f && hops < 60) { const p = f.memoizedProps; if (p && Array.isArray(p.nodes) && Array.isArray(p.edges)) { props = p; break; } f = f.return; hops++; }
const n = props.nodes.find(x => x.id === 'person');
const e = props.edges[0];
({ personNode: { keys: Object.keys(n), measured: n.measured, w: n.width, h: n.height,
