   firstEdge: { id: e.id, s: e.source, t: e.target, sh: e.sourceHandle, th: e.targetHandle, type: e.type } })

// Inspect the edges layer + any react-flow warnings surfaced in the DOM.
const svg = document.querySelector('.react-flow__edges');
const vp = document.querySelector('.react-flow__viewport');
({
  edgesSvgTag: svg?.tagName,
  edgesSvgChildCount: svg?.children.length,
  edgesSvgChildTags: [...(svg?.children||[])].map(c => c.tagName + '.' + c.getAttribute('class')).slice(0,5),
  viewportChildren: [...(vp?.children||[])].map(c => c.getAttribute('class')).slice(0,6),
  reactFlowClasses: document.querySelector('.react-flow')?.getAttribute('class'),
})

// Walk fibers to find the zustand store (has getState with nodeLookup).
const host = document.querySelector('.react-flow');
const key = Object.keys(host).find(k => k.startsWith('__reactFiber$'));
let f = host[key], store = null, hops = 0;
while (f && hops < 120) {
  const deps = [f.memoizedState, f.memoizedProps, f.stateNode];
  for (const d of deps) {
    if (d && typeof d === 'object') {
      for (const v of Object.values(d)) {
        if (v && typeof v.getState === 'function') { try { const st = v.getState(); if (st && st.nodeLookup) { store = st; } } catch {} }
      }
    }
  }
  if (store) break;
  f = f.return; hops++;
}
if (!store) { ({ error: 'store not found', hops }) } else {
  const person = store.nodeLookup.get('person');
  ({ storeFound: true,
     nodeLookupSize: store.nodeLookup.size,
     edgeCount: store.edges?.length,
     personHandles: person?.internals?.handleBounds,
  })
}

