import { type UseQueryResult, useQueries } from "@tanstack/react-query";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type RelationshipTypeRule,
	useEntityTypes,
	useRelationshipTypeRules,
	useRelationshipTypes,
} from "@/lib/api/entities";
import {
	buildLaidOutSchemaGraph,
	type RulesBySlug,
	type SchemaGraph,
	selectRelationshipTypesForGraph,
} from "./entity-schema-graph";

/** Shown until the first ELK run settles, and after a layout failure. */
const EMPTY_GRAPH: SchemaGraph = {
	nodes: [],
	edges: [],
	clusters: [],
	islandSlugs: [],
};

/**
 * Data for the entity-type ERD.
 *
 * Unlike `useVisibleEntityTypes` (rail + scope bar) this KEEPS system types —
 * `$resource` is the ACL anchor for Slack channels and GitHub repos, so it is
 * one of the more informative nodes on the map. They are flagged, not dropped,
 * and the view colors them differently.
 *
 * Rules are fetched per relationship type (`list_rules` takes one slug), so this
 * is 1+N requests where N is the unique relationship-type count. A bulk rules
 * action can replace only this hook later;
 * `buildLaidOutSchemaGraph` is pure and does not care where rules came from.
 */
export function useEntitySchemaGraph(ownerSlug: string) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const {
		data: entityTypes = [],
		isLoading: isTypesLoading,
		isError: isTypesError,
	} = useEntityTypes(orgContext);
	const {
		data: relationshipTypes = [],
		isLoading: isRelTypesLoading,
		isError: isRelTypesError,
	} = useRelationshipTypes(orgContext);

	const scopedTypes = useMemo(
		() =>
			entityTypes.filter(
				(et) => !et.organization_slug || et.organization_slug === ownerSlug,
			),
		[entityTypes, ownerSlug],
	);

	const resolvedRelationshipTypes = useMemo(
		() => selectRelationshipTypesForGraph(relationshipTypes),
		[relationshipTypes],
	);

	const combineRuleQueries = useCallback(
		(results: UseQueryResult<RelationshipTypeRule[]>[]) => {
			const bySlug: RulesBySlug = {};
			resolvedRelationshipTypes.forEach((rt, idx) => {
				const rules = results[idx]?.data;
				if (rules?.length) bySlug[rt.slug] = rules;
			});
			return {
				rulesBySlug: bySlug,
				isRulesLoading: results.some((result) => result.isLoading),
				isRulesError: results.some((result) => result.isError),
			};
		},
		[resolvedRelationshipTypes],
	);

	// One `list_rules` per relationship type, run in parallel. `useQueries` takes
	// a dynamic-length list, so the query count can track the type count without
	// violating the rules of hooks.
	//
	// `.queryOptions()` does not carry the hook's `enabled` predicate, so gate
	// explicitly when there is no org context.
	const { rulesBySlug, isRulesLoading, isRulesError } = useQueries({
		queries: resolvedRelationshipTypes.map((rt) => ({
			...useRelationshipTypeRules.queryOptions(rt.slug, orgContext),
			enabled: hasOrgContext,
		})),
		// Fold the per-slug results in `combine` so the returned map is memoized on
		// the query results themselves. The callback must also be stable: TanStack
		// recomputes a combined result when the function identity changes.
		// Only derive rule-query state here. Entity types are not inputs to
		// `combine`, so graph construction belongs in the `useMemo` below.
		combine: combineRuleQueries,
	});

	// ELK's API is promise-based, so the laid-out graph arrives after the render
	// that requested it and has to live in state rather than a `useMemo`.
	const [graph, setGraph] = useState<SchemaGraph>(EMPTY_GRAPH);
	const [isLayingOut, setIsLayingOut] = useState(false);
	const [didLayoutFail, setDidLayoutFail] = useState(false);

	useEffect(() => {
		// Two layout runs can be in flight when the inputs change mid-run, and
		// they are not guaranteed to settle in order. Ignore all but the newest,
		// or a slow earlier run can overwrite the current graph.
		let cancelled = false;
		setIsLayingOut(true);
		setDidLayoutFail(false);

		buildLaidOutSchemaGraph({
			entityTypes: scopedTypes,
			relationshipTypes: resolvedRelationshipTypes,
			rulesBySlug,
			ownerSlug,
		})
			.then((next) => {
				if (cancelled) return;
				setGraph(next);
				setIsLayingOut(false);
			})
			.catch(() => {
				// A layout failure must not strand the canvas in a permanent
				// skeleton; surface it as an error the view already knows how to
				// render.
				if (cancelled) return;
				setGraph(EMPTY_GRAPH);
				setIsLayingOut(false);
				setDidLayoutFail(true);
			});

		return () => {
			cancelled = true;
		};
	}, [scopedTypes, resolvedRelationshipTypes, rulesBySlug, ownerSlug]);

	return {
		graph,
		// Edges arrive after nodes; treat the canvas as loading until rules settle
		// so the diagram never flashes a disconnected set of boxes. Layout itself
		// is part of that wait now that it is async.
		isLoading:
			isTypesLoading || isRelTypesLoading || isRulesLoading || isLayingOut,
		isError: isTypesError || isRelTypesError || isRulesError || didLayoutFail,
		hasTypes: scopedTypes.length > 0,
	};
}

import { useNavigate } from "@tanstack/react-router";
import type { ReactNode } from "react";
import { useEffect } from "react";
import { useWorkspaceRoot } from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";

export interface OwnerWorkspaceGateProps {
	owner: string;
	children: (props: {
		organizationId: string | null;
		ownerSlug: string;
		isWorkspaceLoading: boolean;
	}) => ReactNode;
}

/**
 * Resolves the org workspace for owner-scoped pages. Always renders children;
 * while workspace is loading passes `organizationId: null` so consumers paint
 * page chrome immediately and swap in shape-matched body skeletons.
 */
export function OwnerWorkspaceGate({
	owner,
	children,
}: OwnerWorkspaceGateProps) {
	const { data, isLoading, isError } = useWorkspaceRoot(owner, { slug: owner });
	const { session, isReady: authReady } = useAuthState();
	const navigate = useNavigate();

	useEffect(() => {
		// `isError` is part of the condition because a failed request has no
		// workspace either. Without it, a 500 for a signed-out visitor bounced them
		// to the login page, which reads as "you are not allowed here" rather than
		// "the server is down".
		if (!isLoading && !isError && authReady && !session && !data?.workspace) {
			void navigate({
				to: "/auth/login",
				search: {
					callbackUrl: window.location.pathname + window.location.search,
					mode: undefined,
					error: undefined,
					errorDescription: undefined,
					loginHint: undefined,
					invitationOrg: undefined,
					intent: "sign-in",
				},
				replace: true,
			});
		}
	}, [isLoading, isError, authReady, session, data, navigate]);

	const workspace = data?.workspace;

	if (isLoading) {
		return (
			<>
				{children({
					organizationId: null,
					ownerSlug: owner,
					isWorkspaceLoading: true,
				})}
			</>
		);
	}

	// A failed request leaves `data` undefined exactly like a real 404 does, so
	// this must be checked BEFORE the missing-workspace branch. Reporting an
	// outage as "Organization not found" sent people off to re-check a slug that
	// was correct all along.
	if (isError) {
		return (
			<div
				role="alert"
				className="flex flex-col items-center justify-center gap-1 py-12 text-center"
			>
				<p className="text-muted-foreground">
					This workspace could not be loaded.
				</p>
				<p className="text-xs text-muted-foreground/70">
					Something went wrong on our end — try again in a moment.
				</p>
			</div>
		);
	}

	if (!workspace) {
		return (
			<div className="flex items-center justify-center py-12 text-muted-foreground">
				Organization not found
			</div>
		);
	}

	if (workspace.type !== "organization") {
		return (
			<div className="flex flex-1 flex-col items-center justify-center gap-2 py-16 text-center">
				<p className="text-muted-foreground max-w-md">
					Select an organization to view this page.
				</p>
			</div>
		);
	}

	return (
		<>
			{children({
				organizationId: workspace.id,
				ownerSlug: workspace.slug,
				isWorkspaceLoading: false,
			})}
		</>
	);
}

// @vitest-environment jsdom
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = {
	data: undefined as { workspace?: unknown } | undefined,
	isLoading: false,
	isError: false,
	error: null as Error | null,
	session: { user: { id: "u1" } } as unknown,
};

vi.mock("@/lib/api", () => ({
	useWorkspaceRoot: () => ({
		data: mocks.data,
		isLoading: mocks.isLoading,
		isError: mocks.isError,
		error: mocks.error,
	}),
}));

vi.mock("@/lib/auth-state", () => ({
	useAuthState: () => ({ session: mocks.session, isReady: true }),
}));

const navigateSpy = vi.fn();
vi.mock("@tanstack/react-router", () => ({
	useNavigate: () => navigateSpy,
}));

import { OwnerWorkspaceGate } from "./owner-workspace-gate";

beforeEach(() => {
	mocks.data = undefined;
	mocks.isLoading = false;
	mocks.isError = false;
	mocks.error = null;
	mocks.session = { user: { id: "u1" } };
	navigateSpy.mockReset();
});

function renderGate() {
	return render(
		<OwnerWorkspaceGate owner="acme">
			{({ organizationId }) => <div data-testid="body">{organizationId}</div>}
		</OwnerWorkspaceGate>,
	);
}

describe("OwnerWorkspaceGate", () => {
	it("reports a server failure as an error, not as a missing organization", () => {
		// A 500 leaves `data` undefined exactly like a real 404 does. Keying the
		// empty state on `!workspace` alone told the user their org did not exist
		// when the server had actually failed — sending them to re-check a slug
		// that was correct all along.
		mocks.isError = true;
		mocks.error = new Error("Request failed with status 500");

		renderGate();

		expect(screen.queryByText("Organization not found")).toBeNull();
		expect(screen.getByRole("alert")).toBeTruthy();
		expect(screen.getByText(/could not be loaded/i)).toBeTruthy();
	});

	it("still reports a genuinely missing organization as not found", () => {
		// The 404 path must keep its own wording — the fix must not turn every
		// missing org into a scary server error.
		mocks.data = {};

		renderGate();

		expect(screen.getByText("Organization not found")).toBeTruthy();
		expect(screen.queryByRole("alert")).toBeNull();
	});

	it("renders the workspace body once it resolves", () => {
		mocks.data = {
			workspace: { type: "organization", id: "org_1", slug: "acme" },
		};

		renderGate();

		expect(screen.getByTestId("body").textContent).toBe("org_1");
	});

	it("does not show either empty state while the request is in flight", () => {
		mocks.isLoading = true;

		renderGate();

		expect(screen.queryByText("Organization not found")).toBeNull();
		expect(screen.queryByRole("alert")).toBeNull();
		expect(screen.getByTestId("body")).toBeTruthy();
	});

	it("does not bounce an errored request to the login page", () => {
		// The redirect fires on "no session and no workspace". A failed request
		// also has no workspace, so an unauthenticated 500 logged the user out of
		// the page they were on instead of surfacing the outage.
		mocks.session = null;
		mocks.isError = true;
		mocks.error = new Error("boom");

		renderGate();

		expect(navigateSpy).not.toHaveBeenCalled();
	});
});

