const nodes=[...document.querySelectorAll('.react-flow__node')];
const out=nodes.slice(0,4).map(n=>{
  const r=n.getBoundingClientRect();
  const inner=n.firstElementChild;
  const ir=inner?inner.getBoundingClientRect():null;
  const hs=[...n.querySelectorAll('.react-flow__handle')].map(h=>{
    const hr=h.getBoundingClientRect();
    return {id:h.getAttribute('data-handleid'), pos:h.className.match(/handle-(left|right|top|bottom)/)?.[1], x:Math.round(hr.x), y:Math.round(hr.y), w:Math.round(hr.width),h:Math.round(hr.height)};
  });
  return {label:n.textContent.slice(0,14), nodeRect:{x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height)},
    innerStyle: inner? inner.getAttribute('style'):null,
    innerRect: ir?{w:Math.round(ir.width),h:Math.round(ir.height)}:null,
    handles:hs};
});
JSON.stringify({nodeCount:nodes.length, edgePaths:document.querySelectorAll('.react-flow__edge-path').length, out},null,1)

