// Walk fiber to find the ReactFlow store (zustand) and inspect nodeLookup/connectionLookup
function fibers(){const el=document.querySelector('.react-flow');const k=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));return el[k];}
let f=fibers(); let found=null; let seen=0;
// climb up to find provider value containing store
let cur=f;
while(cur&&seen<200){seen++;
  const mem=cur.memoizedProps;
  if(mem&&mem.value&&typeof mem.value.getState==='function'){found=mem.value;break;}
  cur=cur.return;
}
if(!found){
 // search down
 const stack=[f];let n=0;
 while(stack.length&&n<20000){n++;const x=stack.pop();if(!x)continue;
  const mp=x.memoizedProps;
  if(mp&&mp.value&&typeof mp.value.getState==='function'){found=mp.value;break;}
  if(x.child)stack.push(x.child); if(x.sibling)stack.push(x.sibling);
 }
}
if(!found) 'NO STORE FOUND';
else {
 const s=found.getState();
 const keys=Object.keys(s);
 const nl=s.nodeLookup; const el2=s.edges;
 const sample=[];
 if(nl){ for(const [k,v] of nl){ sample.push({id:k, measured:v.measured, pos:v.internals&&v.internals.positionAbsolute, handles:(v.internals&&v.internals.handleBounds)?{s:(v.internals.handleBounds.source||[]).map(h=>h.id), t:(v.internals.handleBounds.target||[]).map(h=>h.id)}:null}); if(sample.length>=3)break; } }
 JSON.stringify({storeKeys:keys.slice(0,60), edgeCount:el2?el2.length:null, nodeLookupSize:nl?nl.size:null, sample},null,1)
}

function findStore(){const el=document.querySelector('.react-flow');const k=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));let f=el[k];let cur=f,seen=0;
 while(cur&&seen<200){seen++;const mem=cur.memoizedProps;if(mem&&mem.value&&typeof mem.value.getState==='function')return mem.value;cur=cur.return;}
 const stack=[f];let n=0;while(stack.length&&n<20000){n++;const x=stack.pop();if(!x)continue;const mp=x.memoizedProps;if(mp&&mp.value&&typeof mp.value.getState==='function')return mp.value;if(x.child)stack.push(x.child);if(x.sibling)stack.push(x.sibling);}
 return null;}
const s=findStore().getState();
const nl=s.nodeLookup;
const hb=[];
for(const [k,v] of nl){
  const b=v.internals&&v.internals.handleBounds;
  hb.push({id:k, w:v.measured&&v.measured.width, h:v.measured&&v.measured.height,
    src:b&&b.source?b.source.map(x=>x.id):null, tgt:b&&b.target?b.target.map(x=>x.id):null});
}
const e=s.edges.map(x=>({id:x.id,s:x.source,t:x.target,sh:x.sourceHandle,th:x.targetHandle}));
JSON.stringify({nodesInitialized:s.nodesInitialized, edgeLookupSize:s.edgeLookup?s.edgeLookup.size:null, edges:e, handleBounds:hb.filter(x=>x.src||x.tgt)},null,1)

function findStore(){const el=document.querySelector('.react-flow');const k=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));let f=el[k];let cur=f,seen=0;
 while(cur&&seen<200){seen++;const mem=cur.memoizedProps;if(mem&&mem.value&&typeof mem.value.getState==='function')return mem.value;cur=cur.return;}
 const stack=[f];let n=0;while(stack.length&&n<20000){n++;const x=stack.pop();if(!x)continue;const mp=x.memoizedProps;if(mp&&mp.value&&typeof mp.value.getState==='function')return mp.value;if(x.child)stack.push(x.child);if(x.sibling)stack.push(x.sibling);}
 return null;}
const s=findStore().getState();
const rows=[];
for(const [k,v] of s.nodeLookup){
  const b=v.internals&&v.internals.handleBounds;
  rows.push({id:k, mw:v.measured?v.measured.width:null, mh:v.measured?v.measured.height:null,
    hasHB: !!b, nSrc:b&&b.source?b.source.length:0, nTgt:b&&b.target?b.target.length:0});
}
JSON.stringify({nodesInitialized:s.nodesInitialized, unmeasured: rows.filter(r=>!r.mw||!r.mh), noHandleBounds: rows.filter(r=>!r.hasHB).map(r=>r.id), all: rows},null,1)

