const n=document.querySelector('.react-flow__node');
const r=n.getBoundingClientRect();
const cs=getComputedStyle(n);
// Does a fresh ResizeObserver see a real size for this exact element?
const obs = await new Promise(res=>{
  let done=false;
  const ro=new ResizeObserver(entries=>{
    if(done)return; done=true;
    const e=entries[0];
    res({contentRect:{w:e.contentRect.width,h:e.contentRect.height},
         borderBox: e.borderBoxSize?{w:e.borderBoxSize[0].inlineSize,h:e.borderBoxSize[0].blockSize}:null});
    ro.disconnect();
  });
  ro.observe(n);
  setTimeout(()=>{if(!done){done=true;res('NO CALLBACK');ro.disconnect();}},1500);
});
JSON.stringify({
 wrapperStyle:n.getAttribute('style'),
 rect:{w:r.width,h:r.height},
 display:cs.display, position:cs.position, visibility:cs.visibility,
 offset:{w:n.offsetWidth,h:n.offsetHeight},
 freshObserver: obs,
 ROexists: typeof ResizeObserver,
 zoom: document.querySelector('.react-flow__viewport')?.getAttribute('style')
},null,1)

