1	import ELK from "elkjs/lib/elk.bundled.js";
2	import type {
3		EntityType,
4		RelationshipType,
5		RelationshipTypeRule,
6	} from "@/lib/api";
7	import { isSystemEntityType } from "@/lib/reserved";
8	
9	/**
10	 * Pure model + layout for the entity-type ERD.
11	 *
12	 * Boxes are entity TYPES (not rows); edges are the DECLARED
13	 * `entity_relationship_type_rules` (source→target slug pairs), so the diagram
14	 * renders correctly even for an org with zero entity rows. Kept free of React
15	 * and of the data-fetching layer so the shape logic is unit-testable and the
16	 * rules source can change (per-slug fan-out today, a bulk endpoint later)
17	 * without touching the view.
18	 */
19	
20	/** A field row rendered inside a type's box. */
21	export interface SchemaNodeField {
22		name: string;
23		/** JSON-schema type, when the property declares one. */
24		type?: string;
25	}
26	
27	export interface SchemaNodeData {
28		slug: string;
29		label: string;
30		/** Owner slug, so a node can link straight to its entity-type editor. */
31		ownerSlug: string;
32		icon?: string | null;
33		fields: SchemaNodeField[];
34		/** Reserved `$…` type, rendered in a distinct color rather than hidden. */
35		isSystem: boolean;
36		entityCount?: number;
37		/** Edge-specific handles keep parallel relationships from overlapping. */
38		sourceHandleIds: string[];
39		targetHandleIds: string[];
40		/** Self-loop targets attach above the node so their paths remain visible. */
41		selfTargetHandleIds: string[];
42		/**
43		 * Set by the view when a cluster is focused and this type is not in it.
44		 * Layout does not compute it — it is view state, carried on the node because
45		 * React Flow only hands the renderer `data`.
46		 */
47		isDimmed?: boolean;
48		/**
49		 * Where layout last placed this node. Compared against the next layout's
50		 * position so a re-layout can be told apart from a user drag.
51		 */
52		laidOutPosition?: { x: number; y: number };
53	}
54	
55	interface SchemaEdgeData {
56		/** Relationship type slug (`works_at`), not the rule id. */
57		slug: string;
58		label: string;
59		/** Symmetric relations render without an arrowhead — the pair is unordered. */
60		isSymmetric: boolean;
61		/**
62		 * How many declared rules this one drawn edge stands for.
63		 *
64		 * Sibling rules of one relationship type on the same ordered pair are drawn
65		 * once with a count rather than as parallel paths: they carry identical text
66		 * and identical endpoints, so N paths added N crossings and zero information.
67		 */
68		ruleCount: number;
69		/** Every rule id folded into this edge, so the view can expand it on demand. */
70		ruleIds: number[];
71	}
72	
73	export interface SchemaGraphNode {
74		id: string;
75		data: SchemaNodeData;
76		position: { x: number; y: number };
77		width: number;
78		height: number;
79	}
80	
81	export interface SchemaGraphEdge {
82		id: string;
83		source: string;
84		target: string;
85		data: SchemaEdgeData;
86	}
87	
88	export interface SchemaGraph {
89		nodes: SchemaGraphNode[];
90		edges: SchemaGraphEdge[];
91		/** Connected components, biggest first. Islands are excluded — see `schemaClusters`. */
92		clusters: SchemaCluster[];
93		/** Slugs of types no declared rule touches, in the order they are laid out. */
94		islandSlugs: string[];
95	}
96	
97	/** Rules keyed by the relationship-type slug they belong to. */
98	export type RulesBySlug = Record<string, RelationshipTypeRule[]>;
99	
100	/**
101	 * Which edges should carry a visible label.
102	 *
103	 * Parallel edges between the same pair stack identical text in the same spot,
104	 * so only the first of a pair is labelled. Keyed by the PAIR rather than by
105	 * relationship type: one type can join several different pairs (`contains`
106	 * covers order→product and invoice→payment), and keying by type alone would
107	 * caption an unrelated pair with the first pair's name.
108	 */
109	export function labelledEdgeIds(edges: SchemaGraphEdge[]): Set<string> {
110		const seenPairs = new Set<string>();
111		const labelled = new Set<string>();
112		for (const edge of edges) {
113			const pairKey = `${edge.data.slug}|${edge.source}|${edge.target}`;
114			if (seenPairs.has(pairKey)) continue;
115			seenPairs.add(pairKey);
116			labelled.add(edge.id);
117		}
118		return labelled;
119	}
120	
121	const NODE_WIDTH = 220;
122	const HEADER_HEIGHT = 44;
123	
124	function compareSlugs(a: { slug: string }, b: { slug: string }): number {
125		return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
126	}
127	
128	/**
129	 * Keep active relationship types only. The accessible list is tenant-first and
130	 * may also contain a public type with the same slug; `list_rules` resolves that
131	 * slug tenant-first, so keep the first type to label its rules consistently.
132	 */
133	export function selectRelationshipTypesForGraph(
134		relationshipTypes: RelationshipType[],
135	): RelationshipType[] {
