 * are laid out; unconnected types have no edge to rank them and get their own
 * column at the top left.
 */
const elk = new ELK();

/** Tuned for a schema map: wide ranks and room for separate edge paths. */
const ELK_OPTIONS: Record<string, string> = {
	"elk.algorithm": "layered",
	"elk.direction": "RIGHT",
	"elk.edgeRouting": "ORTHOGONAL",
	// These spacings affect the node coordinates ELK returns. React Flow renders
	// the paths itself, using handles in the same edge order supplied here.
	"elk.layered.spacing.edgeEdgeBetweenLayers": "12",
	"elk.layered.spacing.edgeNodeBetweenLayers": "24",
	"elk.layered.spacing.nodeNodeBetweenLayers": "120",
	"elk.spacing.nodeNode": "32",
	"elk.spacing.edgeEdge": "12",
	"elk.spacing.edgeNode": "20",
	// Keep a node's own edges in the order its handles are rendered, so an
	// edge's line meets the handle it is anchored to instead of crossing to it.
	"elk.layered.considerModelOrder.strategy": "NODES_AND_EDGES",
	"elk.layered.crossingMinimization.semiInteractive": "true",
};

