100	 * may also contain a public type with the same slug; `list_rules` resolves that
101	 * slug tenant-first, so keep the first type to label its rules consistently.
102	 */
103	export function selectRelationshipTypesForGraph(
104		relationshipTypes: RelationshipType[],
105	): RelationshipType[] {
106		const seen = new Set<string>();
107		return relationshipTypes.filter((relationshipType) => {
108			if (relationshipType.status !== "active") return false;
109			if (seen.has(relationshipType.slug)) return false;
110			seen.add(relationshipType.slug);
111			return true;
112		});
