116		const schema = entityType.metadata_schema;
117		if (!schema || typeof schema !== "object") return 0;
118		const properties = (schema as Record<string, unknown>).properties;
119		if (!properties || typeof properties !== "object") return 0;
120		return Object.keys(properties).length;
