145		// Keyed by relationship type AND ordered pair: `contains` joining
146		// order→product and invoice→payment is two distinct edges, while two
147		// `works_at` rules on person→company is one edge drawn with a count.
148		const byPair = new Map<string, SchemaGraphEdge>();
