202					label: et.name || et.slug,
203					ownerSlug,
204					icon: et.icon,
205					fieldCount: schemaFieldCount(et),
206					isSystem: isSystemEntityType(et),
207					entityCount: et.entity_count,
208					sourceHandleIds: sourceHandles.get(et.slug) ?? [],
209					targetHandleIds: targetHandles.get(et.slug) ?? [],
210					selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
211				},
212			};
213		});
214	
215		return { nodes, edges };
216	}
