export async function getApiErrorMessage(response: Response): Promise<string> {
  const fallback = `API error: ${response.status}`;
  const raw = await response.text();
  if (!raw) return fallback;

  try {
    const parsed = JSON.parse(raw) as { error?: unknown; message?: unknown };
    if (typeof parsed.message === 'string' && parsed.message.length > 0) return parsed.message;
    if (typeof parsed.error === 'string' && parsed.error.length > 0) return parsed.error;
    return fallback;
  } catch {
    return raw;
  }
}

/**
 * Throw an `Error` with the server-provided message if the response is not ok.
 * Shared by the REST hook modules (previously a byte-identical copy in each).
 * The thrown message prefers the body's `message`/`error` field, falling back
 * to `<fallbackMessage>: <status>`, then the raw body text.
 */
export async function throwIfNotOk(res: Response, fallbackMessage: string): Promise<void> {
  if (res.ok) return;
  const raw = await res.text();
  let message = `${fallbackMessage}: ${res.status}`;
  if (raw) {
    try {
      const parsed = JSON.parse(raw) as { error?: string; message?: string };
      message = parsed.message || parsed.error || message;
    } catch {
      message = raw;
    }
  }
  throw new Error(message);
}

