import { useNavigate } from '@tanstack/react-router';
import type { ReactNode } from 'react';
import { useEffect } from 'react';
import { useWorkspaceRoot } from '@/lib/api';
import { isNotFoundError } from '@/lib/api/core';
import { useAuthState } from '@/lib/auth-state';

export interface OwnerWorkspaceGateProps {
  owner: string;
  children: (props: {
    organizationId: string | null;
    ownerSlug: string;
    isWorkspaceLoading: boolean;
  }) => ReactNode;
}

/**
 * Resolves the org workspace for owner-scoped pages. Always renders children;
 * while workspace is loading passes `organizationId: null` so consumers paint
 * page chrome immediately and swap in shape-matched body skeletons.
 */
export function OwnerWorkspaceGate({ owner, children }: OwnerWorkspaceGateProps) {
  const { data, isLoading, error } = useWorkspaceRoot(owner, { slug: owner });
  const { session, isReady: authReady } = useAuthState();
  const navigate = useNavigate();

  const isNotFound = isNotFoundError(error);
  const isUnavailable = error != null && !isNotFound && !data?.workspace;

  useEffect(() => {
    if (!isLoading && !isUnavailable && authReady && !session && !data?.workspace) {
      void navigate({
        to: '/auth/login',
        search: {
          callbackUrl: window.location.pathname + window.location.search,
          mode: undefined,
          error: undefined,
          errorDescription: undefined,
          loginHint: undefined,
          invitationOrg: undefined,
          intent: 'sign-in',
        },
        replace: true,
      });
    }
  }, [isLoading, isUnavailable, authReady, session, data, navigate]);

  const workspace = data?.workspace;

  if (isLoading) {
    return (
      <>
        {children({
          organizationId: null,
          ownerSlug: owner,
          isWorkspaceLoading: true,
        })}
      </>
    );
  }

  if (isUnavailable) {
    return (
      <div
        role="alert"
        className="flex flex-col items-center justify-center gap-1 py-12 text-center"
      >
        <p className="text-muted-foreground">This workspace could not be loaded.</p>
        <p className="text-xs text-muted-foreground/70">Please try again in a moment.</p>
      </div>
    );
  }

  if (isNotFound || !workspace) {
    return (
      <div className="flex items-center justify-center py-12 text-muted-foreground">
        Organization not found
      </div>
    );
  }

  if (workspace.type !== 'organization') {
    return (
      <div className="flex flex-1 flex-col items-center justify-center gap-2 py-16 text-center">
        <p className="text-muted-foreground max-w-md">
          Select an organization to view this page.
        </p>
      </div>
    );
  }

  return (
    <>
      {children({
        organizationId: workspace.id,
        ownerSlug: workspace.slug,
        isWorkspaceLoading: false,
      })}
    </>
  );
}

