import { render, screen } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { ApiError } from '@/lib/api/core';

const mocks = {
  allOrgs: undefined as unknown[] | undefined,
  error: null as Error | null,
};

vi.mock('@/lib/api', () => ({
  useOrganizations: () => ({ data: mocks.allOrgs, error: mocks.error }),
  updateOrganizationVisibility: vi.fn(),
}));

vi.mock('@/lib/auth', () => ({ organization: {} }));

vi.mock('@/hooks/use-org-context', () => ({
  useOrgContext: () => ({ activeOrg: null, urlOrgSlug: 'acme' }),
}));

vi.mock('@tanstack/react-query', () => ({
  useQueryClient: () => ({ invalidateQueries: vi.fn() }),
}));

vi.mock('@tanstack/react-router', () => ({ useNavigate: () => vi.fn() }));

// The permissions matrix fetches on mount and is irrelevant to these branches.
vi.mock('@/components/agents/agent-permissions-matrix', () => ({
  AgentPermissionsMatrix: () => null,
}));

import { OrganizationSettingsPage } from './organization-settings-page';

beforeEach(() => {
  mocks.allOrgs = undefined;
  mocks.error = null;
});

function org(overrides: Record<string, unknown> = {}) {
  return {
    id: 'org_1',
    slug: 'acme',
    name: 'Acme',
    visibility: 'private',
    is_member: true,
    ...overrides,
  };
}

describe('OrganizationSettingsPage error states', () => {
  it('surfaces an outage instead of spinning forever', () => {
    // The page keyed its skeleton on `allOrgs === undefined`, which a failed
    // request also satisfies — so a 500 left it loading with no way out.
    mocks.error = new ApiError('boom', 500);

    render(<OrganizationSettingsPage owner="acme" />);

    expect(screen.getByRole('alert')).toBeTruthy();
    expect(screen.getByText(/couldn't load organizations/i)).toBeTruthy();
  });

  it('does not call a sign-in prompt an outage', () => {
    // A 401 means "sign in", not "we are broken". The not-a-member card below
    // already says the right thing, so this must fall through to it.
    mocks.error = new ApiError('Unauthorized', 401);
    mocks.allOrgs = [];

    render(<OrganizationSettingsPage owner="acme" />);

    expect(screen.queryByText(/couldn't load organizations/i)).toBeNull();
    expect(screen.getByText('Organization not found')).toBeTruthy();
  });

  it('keeps the settings visible when a background refetch fails', () => {
    // A failed refetch that still has a cached list is not an error state —
    // blanking a working page over it would be a regression.
    mocks.error = new ApiError('boom', 500);
    mocks.allOrgs = [org()];

    render(<OrganizationSettingsPage owner="acme" />);

    expect(screen.queryByRole('alert')).toBeNull();
    expect(screen.queryByText(/couldn't load organizations/i)).toBeNull();
  });
});

