import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';
const SCRATCH = process.env.SCRATCH;
const cookie = readFileSync(`${SCRATCH}/cookie.txt`, 'utf8').trim();
const browser = await chromium.launch({ headless: false, channel: 'chrome' });
const results = {};

async function probe(name, { authed, route, intercept }) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  if (authed) {
    await ctx.addCookies([{ name: 'better-auth.session_token', value: decodeURIComponent(cookie), url: 'http://localhost:5210' }]);
  }
  const page = await ctx.newPage();
  if (intercept) {
    await page.route('**/api/**', async (r) => {
      if (intercept.match.test(r.request().url())) {
        return r.fulfill({ status: intercept.status, contentType: 'application/json', body: JSON.stringify(intercept.body) });
      }
      return r.continue();
    });
  }
  await page.goto(`http://localhost:5210${route}`, { waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(4000);
  const text = await page.evaluate(() => document.body.innerText);
  results[name] = {
    url: page.url(),
    notFound: /Organization not found/i.test(text),
    outage: /could not be loaded|Couldn't load organizations/i.test(text),
    onLogin: /\/auth\/login/.test(page.url()),
    stillLoading: /^\s*$/.test(text) === false && text.length < 40,
  };
  await ctx.close();
}

// 1. 404 — org that genuinely does not exist, signed IN
await probe('404_signed_in', { authed: true, route: '/no-such-org-xyz/memory' });
// 2. 500 — forced server error on resolve_path, signed IN
await probe('500_signed_in', { authed: true, route: '/local-install/memory',
  intercept: { match: /resolve_path/, status: 500, body: { message: 'boom' } } });
// 3. 401 — signed OUT against a real org (the blocker case)
await probe('401_signed_out', { authed: false, route: '/local-install/memory' });

console.log(JSON.stringify(results, null, 1));
await browser.close();
EOF
